AI5C,IAAM,EAAO,MAAM,IAAI,SAAe,EAAS,IAC7C,EAAO,OAAQ,GACb,EAAO,EAAQ,CAAI,EAAI,EAAW,MAAM,0BAA0B,CAAC,CACrE,CACF,EACM,EAAO,GAAG,CAAC,IAAI,KAAO,MACtB,EAAO,IAAI,KAAK,CAAC,CAAI,EAAG,CAAI,EAC5B,EAAS,MAAM,GAAe,EAAM,QAAQ,EAClD,GAAI,CAAC,EAAO,GACV,MAAU,MAAM,iCAAiC,EAAO,QAAQ,EAClE,IAAM,EAAO,EAAO,KACd,EAAa,EAAK,MAAQ,EAGhC,MAAO,GAFW,EAAK,WAAa,SAEhB,GAAG,EAAW,IADrB,EAAK,MAAQ,OACiB,EAC7C,EAEA,IAAM,EAAQ,EAAY,IAAI,CAAI,EAC7B,GACL,EAAW,KAAM,GAAM,CACrB,EAAQ,GAEJ,OAAO,EAAE,OAAU,UAAY,CAAC,EAAE,SACpC,EAAE,MAAQ,EAAM,YAAc,IAC9B,EAAE,MAAQ,EAAM,aAAe,KAEjC,EAAI,SAAW,GACf,EAAI,MAAQ,EAAE,WAAW,CAC3B,CAAC,CACH,CACF,CAAC,EC7IC,YAAM,OAAO","names":[],"ignoreList":[],"sources":["../../src/extensions/core/clipspace.ts","../../src/extensions/core/contextMenuFilter.ts","../../src/extensions/core/createBoundingBoxes.ts","../../src/extensions/core/widgetValuePropagation.ts","../../src/extensions/core/customWidgets.ts","../../src/extensions/core/dynamicPrompts.ts","../../src/extensions/core/editAttention.ts","../../src/constants/groupNodeConstants.ts","../../src/renderer/utils/nodeTypeGuards.ts","../../src/utils/nodeDefUtil.ts","../../src/extensions/core/widgetInputs.ts","../../src/extensions/core/groupNode.ts","../../src/extensions/core/groupOptions.ts","../../src/extensions/core/imageCompare.ts","../../src/extensions/core/imageCompositor.ts","../../src/extensions/core/imageCrop.ts","../../src/extensions/core/layerEditor.ts","../../src/extensions/core/load3dLazy.ts","../../src/extensions/core/maskeditor.ts","../../src/extensions/core/noteNode.ts","../../src/extensions/core/painter.ts","../../src/extensions/core/textPreviewWidgets.ts","../../src/extensions/core/previewAny.ts","../../src/extensions/core/saveText.ts","../../src/extensions/core/rerouteNode.ts","../../src/extensions/core/saveImageExtraOutput.ts","../../src/extensions/core/selectionBorder.ts","../../src/extensions/core/simpleTouchSupport.ts","../../src/extensions/core/slotDefaultTypes.ts","../../src/extensions/core/slotDefaults.ts","../../src/renderer/extensions/vueNodes/widgets/utils/audioUtils.ts","../../src/extensions/core/uploadAudio.ts","../../src/extensions/core/uploadImage.ts","../../src/extensions/core/webcamCapture.ts","../../src/extensions/core/index.ts"],"sourcesContent":["import { app, ComfyApp } from '../../scripts/app'\nimport { ComfyDialog } from '../../scripts/ui'\nimport { $el } from '../../scripts/ui/utils'\n\nclass ClipspaceDialog extends ComfyDialog {\n  static items: Array<\n    HTMLButtonElement & {\n      contextPredicate?: () => boolean\n    }\n  > = []\n  static instance: ClipspaceDialog | null = null\n\n  static registerButton(\n    name: string,\n    contextPredicate: () => boolean,\n    callback: () => void\n  ) {\n    const item = $el('button', {\n      type: 'button',\n      textContent: name,\n      contextPredicate: contextPredicate,\n      onclick: callback\n    })\n\n    ClipspaceDialog.items.push(item)\n  }\n\n  static invalidatePreview() {\n    if (\n      ComfyApp.clipspace &&\n      ComfyApp.clipspace.imgs &&\n      ComfyApp.clipspace.imgs.length > 0\n    ) {\n      const img_preview = document.getElementById('clipspace_preview')\n      if (img_preview instanceof HTMLImageElement) {\n        img_preview.src =\n          ComfyApp.clipspace.imgs[ComfyApp.clipspace['selectedIndex']].src\n        img_preview.style.maxHeight = '100%'\n        img_preview.style.maxWidth = '100%'\n      }\n    }\n  }\n\n  static invalidate() {\n    if (ClipspaceDialog.instance) {\n      const self = ClipspaceDialog.instance\n      // allow reconstruct controls when copying from non-image to image content.\n      const imgSettings = self.createImgSettings()\n      const children = $el('div.comfy-modal-content', [\n        ...(imgSettings ? [imgSettings] : []),\n        ...self.createButtons()\n      ])\n\n      self.element.replaceChildren(children)\n\n      if (self.element.children[0].children.length <= 1) {\n        self.element.children[0].appendChild(\n          $el('p', {}, [\n            'Unable to find the features to edit content of a format stored in the current Clipspace.'\n          ])\n        )\n      }\n\n      ClipspaceDialog.invalidatePreview()\n    }\n  }\n\n  constructor() {\n    super()\n  }\n\n  override createButtons() {\n    const buttons = []\n\n    for (const item of ClipspaceDialog.items) {\n      if (!item.contextPredicate || item.contextPredicate()) buttons.push(item)\n    }\n\n    buttons.push(\n      $el('button', {\n        type: 'button',\n        textContent: 'Close',\n        onclick: () => {\n          this.close()\n        }\n      })\n    )\n\n    return buttons\n  }\n\n  createImgSettings(): HTMLTableElement | null {\n    if (ComfyApp.clipspace?.imgs) {\n      const combo_items = []\n      const imgs = ComfyApp.clipspace.imgs\n\n      for (let i = 0; i < imgs.length; i++) {\n        combo_items.push($el('option', { value: i }, [`${i}`]))\n      }\n\n      const combo1 = $el(\n        'select',\n        {\n          id: 'clipspace_img_selector',\n          onchange: (event: Event) => {\n            if (event.target && ComfyApp.clipspace) {\n              ComfyApp.clipspace['selectedIndex'] = (\n                event.target as HTMLSelectElement\n              ).selectedIndex\n              ClipspaceDialog.invalidatePreview()\n            }\n          }\n        },\n        combo_items\n      )\n\n      const row1 = $el('tr', {}, [\n        $el('td', {}, [$el('font', { color: 'white' }, ['Select Image'])]),\n        $el('td', {}, [combo1])\n      ])\n\n      const combo2 = $el(\n        'select',\n        {\n          id: 'clipspace_img_paste_mode',\n          onchange: (event: Event) => {\n            if (event.target && ComfyApp.clipspace) {\n              ComfyApp.clipspace['img_paste_mode'] = (\n                event.target as HTMLSelectElement\n              ).value\n            }\n          }\n        },\n        [\n          $el('option', { value: 'selected' }, 'selected'),\n          $el('option', { value: 'all' }, 'all')\n        ]\n      )\n      combo2.value = ComfyApp.clipspace['img_paste_mode']\n\n      const row2 = $el('tr', {}, [\n        $el('td', {}, [$el('font', { color: 'white' }, ['Paste Mode'])]),\n        $el('td', {}, [combo2])\n      ])\n\n      const td = $el(\n        'td',\n        { align: 'center', width: '100px', height: '100px', colSpan: '2' },\n        [$el('img', { id: 'clipspace_preview', ondragstart: () => false }, [])]\n      )\n\n      const row3 = $el('tr', {}, [td])\n\n      return $el('table', {}, [row1, row2, row3])\n    } else {\n      return null\n    }\n  }\n\n  createImgPreview(): HTMLImageElement | null {\n    if (ComfyApp.clipspace?.imgs) {\n      return $el('img', { id: 'clipspace_preview', ondragstart: () => false })\n    } else return null\n  }\n\n  override show() {\n    ClipspaceDialog.invalidate()\n\n    this.element.style.display = 'block'\n  }\n}\n\napp.registerExtension({\n  name: 'Comfy.Clipspace',\n  init() {\n    app.openClipspace = function () {\n      if (!ClipspaceDialog.instance) {\n        ClipspaceDialog.instance = new ClipspaceDialog()\n        ComfyApp.clipspace_invalidate_handler = ClipspaceDialog.invalidate\n      }\n\n      if (ComfyApp.clipspace) {\n        ClipspaceDialog.instance.show()\n      } else app.ui.dialog.show('Clipspace is Empty!')\n    }\n  }\n})\n","import type {\n  IContextMenuOptions,\n  IContextMenuValue\n} from '@/lib/litegraph/src/types/contextMenu'\nimport type { ContextMenu } from '@/lib/litegraph/src/litegraph'\nimport {\n  LGraphCanvas,\n  LiteGraph,\n  isComboWidget\n} from '@/lib/litegraph/src/litegraph'\n\nimport { app } from '../../scripts/app'\n\n// Adds filtering to combo context menus\n\ntype ContextMenuArgs = ConstructorParameters<typeof ContextMenu>\n\nfunction addFilter(\n  ctx: ContextMenu,\n  values: readonly (string | IContextMenuValue | null)[],\n  options: IContextMenuOptions = {}\n): ContextMenu {\n  // If we are a dark menu (only used for combo boxes) then add a filter input\n  if (options.className === 'dark' && values.length > 4) {\n    const filter = document.createElement('input')\n    filter.classList.add('comfy-context-menu-filter')\n    filter.placeholder = 'Filter list'\n\n    ctx.root.prepend(filter)\n\n    const items = Array.from(\n      ctx.root.querySelectorAll('.litemenu-entry')\n    ) as HTMLElement[]\n    let displayedItems = [...items]\n    let itemCount = displayedItems.length\n\n    // We must request an animation frame for the current node of the active canvas to update.\n    requestAnimationFrame(() => {\n      const currentNode = LGraphCanvas.active_canvas.current_node\n      const clickedComboValue = currentNode?.widgets\n        ?.filter(isComboWidget)\n        .find(\n          ({ options: { values: widgetValues } }) =>\n            Array.isArray(widgetValues) &&\n            widgetValues.length === values.length &&\n            widgetValues.every((v, i) => v === values[i])\n        )?.value\n\n      let selectedIndex = clickedComboValue\n        ? values.findIndex(\n            (v) => typeof v === 'string' && v === clickedComboValue\n          )\n        : 0\n      if (selectedIndex < 0) {\n        selectedIndex = 0\n      }\n      let selectedItem = displayedItems.at(selectedIndex)\n      updateSelected()\n\n      // Apply highlighting to the selected item\n      function updateSelected() {\n        selectedItem?.style.setProperty('background-color', '')\n        selectedItem?.style.setProperty('color', '')\n        selectedItem = displayedItems.at(selectedIndex)\n        selectedItem?.style.setProperty('background-color', '#ccc', 'important')\n        selectedItem?.style.setProperty('color', '#000', 'important')\n      }\n\n      const positionList = () => {\n        const rect = ctx.root.getBoundingClientRect()\n\n        // If the top is off-screen then shift the element with scaling applied\n        if (rect.top < 0) {\n          const scale =\n            1 - ctx.root.getBoundingClientRect().height / ctx.root.clientHeight\n\n          const shift = (ctx.root.clientHeight * scale) / 2\n\n          ctx.root.style.top = -shift + 'px'\n        }\n      }\n\n      // Arrow up/down to select items\n      filter.addEventListener('keydown', (event) => {\n        switch (event.key) {\n          case 'ArrowUp':\n            event.preventDefault()\n            if (selectedIndex === 0) {\n              selectedIndex = itemCount - 1\n            } else {\n              selectedIndex--\n            }\n            updateSelected()\n            break\n          case 'ArrowRight':\n            event.preventDefault()\n            selectedIndex = itemCount - 1\n            updateSelected()\n            break\n          case 'ArrowDown':\n            event.preventDefault()\n            if (selectedIndex === itemCount - 1) {\n              selectedIndex = 0\n            } else {\n              selectedIndex++\n            }\n            updateSelected()\n            break\n          case 'ArrowLeft':\n            event.preventDefault()\n            selectedIndex = 0\n            updateSelected()\n            break\n          case 'Enter':\n            selectedItem?.click()\n            break\n          case 'Escape':\n            ctx.close()\n            break\n        }\n      })\n\n      filter.addEventListener('input', () => {\n        // Hide all items that don't match our filter\n        const term = filter.value.toLocaleLowerCase()\n        // When filtering, recompute which items are visible for arrow up/down and maintain selection.\n        displayedItems = items.filter((item) => {\n          const isVisible =\n            !term || item.textContent.toLocaleLowerCase().includes(term)\n          item.style.display = isVisible ? 'block' : 'none'\n          return isVisible\n        })\n\n        selectedIndex = Math.max(\n          0,\n          displayedItems.findIndex((d) => d === selectedItem)\n        )\n        itemCount = displayedItems.length\n\n        updateSelected()\n\n        // If we have an event then we can try and position the list under the source\n        if (options.event) {\n          let top = options.event.clientY - 10\n\n          const bodyRect = document.body.getBoundingClientRect()\n\n          const rootRect = ctx.root.getBoundingClientRect()\n          if (bodyRect.height && top > bodyRect.height - rootRect.height - 10) {\n            top = Math.max(0, bodyRect.height - rootRect.height - 10)\n          }\n\n          ctx.root.style.top = top + 'px'\n          positionList()\n        }\n      })\n\n      requestAnimationFrame(() => {\n        // Focus the filter box when opening\n        filter.focus()\n\n        positionList()\n      })\n    })\n  }\n  return ctx\n}\n\nconst ext = {\n  name: 'Comfy.ContextMenuFilter',\n  init() {\n    // Custom nodes wrap this with `orig.call(this, ...)`, so it must stay callable\n    LiteGraph.ContextMenu = new Proxy(LiteGraph.ContextMenu, {\n      construct: (target, args: ContextMenuArgs) =>\n        addFilter(new target(...args), ...args),\n      apply: (target, _thisArg, args: ContextMenuArgs) =>\n        addFilter(new target(...args), ...args)\n    })\n  }\n}\n\napp.registerExtension(ext)\n","import { useExtensionService } from '@/services/extensionService'\n\nconst INTERNAL_WIDGETS = new Set(['last_incoming'])\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.CreateBoundingBoxes',\n\n  nodeCreated(node) {\n    if (node.constructor.comfyClass !== 'CreateBoundingBoxes') return\n\n    const [oldWidth, oldHeight] = node.size\n    node.setSize([Math.max(oldWidth, 420), Math.max(oldHeight, 560)])\n\n    for (const widget of node.widgets ?? []) {\n      if (INTERNAL_WIDGETS.has(widget.name)) widget.hidden = true\n    }\n  }\n})\n","import type { Point } from '@/lib/litegraph/src/interfaces'\nimport type { LLink } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { CanvasPointerEvent } from '@/lib/litegraph/src/types/events'\nimport { app } from '@/scripts/app'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport type { NodeId } from '@/types/nodeId'\nimport type { WidgetValue } from '@/types/simplifiedWidget'\n\ntype SourceNode = Pick<LGraphNode, 'id' | 'graph' | 'widgets'>\n\ninterface TargetEndpoint {\n  targetNodeId: NodeId\n  targetSlot: number\n}\n\nexport function applyFirstWidgetValueToGraph(\n  node: SourceNode,\n  extraLinks: LLink[] = [],\n  transformValue?: (value: WidgetValue) => WidgetValue\n) {\n  const { graph } = node\n  if (!graph) return\n\n  const linked = [\n    ...useLinkStore().getOutputSlotLinks(graphScopeOf(graph), node.id, 0)\n  ]\n  if (!linked.length) return\n\n  const sourceWidget = node.widgets?.[0]\n  if (!sourceWidget) return\n\n  let value = sourceWidget.value\n  if (transformValue) {\n    value = transformValue(value)\n  }\n\n  const graphMouse: Point = app.canvas.graph_mouse\n\n  const endpoints: TargetEndpoint[] = [\n    ...linked.map(({ targetNodeId, targetSlot }) => ({\n      targetNodeId,\n      targetSlot\n    })),\n    ...extraLinks.map((link) => ({\n      targetNodeId: link.target_id,\n      targetSlot: link.target_slot\n    }))\n  ]\n\n  for (const endpoint of endpoints) {\n    const targetNode = graph.getNodeById(endpoint.targetNodeId)\n    const input = targetNode?.inputs[endpoint.targetSlot]\n    if (!targetNode || !input) {\n      console.warn('Unable to resolve node or input for link', endpoint)\n      continue\n    }\n\n    const widgetName = input.widget?.name\n    if (!widgetName) {\n      console.warn('Invalid widget or widget name', input.widget)\n      continue\n    }\n\n    const targetWidget = targetNode.widgets?.find(\n      (widget) => widget.name === widgetName\n    )\n    if (!targetWidget) {\n      console.warn(\n        `Unable to find widget \"${widgetName}\" on node [${targetNode.id}]`\n      )\n      continue\n    }\n\n    targetWidget.value = value\n    targetWidget.callback?.(\n      targetWidget.value,\n      app.canvas,\n      targetNode,\n      graphMouse,\n      {} as CanvasPointerEvent\n    )\n  }\n}\n","import { clamp } from 'es-toolkit'\nimport { computed, shallowReactive } from 'vue'\n\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { LLink } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { BaseWidget } from '@/lib/litegraph/src/widgets/BaseWidget'\nimport type { ComfyNodeDef } from '@/schemas/nodeDefSchema'\nimport { app } from '@/scripts/app'\nimport { GET_CONFIG } from '@/services/litegraphService'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport type { WidgetValue } from '@/types/simplifiedWidget'\n\nimport { applyFirstWidgetValueToGraph } from './widgetValuePropagation'\nimport { widgetId } from '@/types/widgetId'\n\nfunction applyToGraph(this: LGraphNode, extraLinks: LLink[] = []) {\n  applyFirstWidgetValueToGraph(this, extraLinks)\n}\n\n/**\n * `node.resolveInput` only exists on the `ExecutableNodeDTO` used while\n * building the API prompt (see `executionUtil.ts`), not on `LGraphNode`\n * itself. Prompt serialization is the only place that can resolve a\n * promoted widget's per-host value, so this is a runtime duck-type check\n * rather than a static one.\n */\ntype LinkedInputResolver = {\n  resolveInput: (\n    slot: number\n  ) => { widgetInfo?: { value: unknown } } | undefined\n}\n\nfunction hasLinkedInputResolver(\n  node: LGraphNode\n): node is LGraphNode & LinkedInputResolver {\n  return (\n    typeof (node as Partial<LinkedInputResolver>).resolveInput === 'function'\n  )\n}\n\n/**\n * Resolves the choice widget's current effective value.\n *\n * Per ADR-SUBGRAPH-PROMOTION-0009, a promoted widget's host value is not mirrored back onto\n * the interior widget, so `comboWidget.value` is only accurate when\n * `choice` hasn't been converted to a linked subgraph input. When it has,\n * the live value must be resolved the same way prompt serialization\n * resolves any other linked widget input: `resolverNode` is the\n * execution-scoped node passed into `serializeValue`, which is what's\n * actually able to walk the link to the promoted host value.\n */\nfunction resolveChoiceValue(\n  interiorNode: LGraphNode,\n  comboWidget: IBaseWidget,\n  resolverNode: LGraphNode = interiorNode\n) {\n  const choiceInputIndex = interiorNode.inputs.findIndex(\n    (input) => input.widget?.name === comboWidget.name\n  )\n  if (choiceInputIndex < 0 || !hasLinkedInputResolver(resolverNode)) {\n    return comboWidget.value\n  }\n\n  const resolved = resolverNode.resolveInput(choiceInputIndex)\n  // `resolved.widgetInfo` is only set when the link resolves back to a\n  // promoted widget. When `choice` is linked to a real node's output\n  // instead, there is no widget to read a value from here -- resolving that\n  // upstream execution-time value is out of scope for this fix, so this\n  // falls back to the (possibly stale) interior widget value.\n  return resolved?.widgetInfo ? resolved.widgetInfo.value : comboWidget.value\n}\n\nfunction onCustomComboCreated(this: LGraphNode) {\n  this.applyToGraph = applyToGraph\n\n  const comboWidget = this.widgets![0]\n  const values = shallowReactive<string[]>([])\n  comboWidget.options.values = values\n\n  const updateCombo = () => {\n    values.splice(\n      0,\n      values.length,\n      ...this.widgets!.filter(\n        (w) => w.name.startsWith('option') && w.value\n      ).map((w) => `${w.value}`)\n    )\n    if (app.configuringGraph || !this.graph) return\n    if (values.includes(`${comboWidget.value}`)) return\n    comboWidget.value = values.at(0) ?? ''\n    comboWidget.callback?.(comboWidget.value)\n  }\n  comboWidget.callback = useChainCallback(comboWidget.callback, () =>\n    this.applyToGraph!()\n  )\n  this.onAdded = useChainCallback(this.onAdded, function () {\n    updateCombo()\n  })\n\n  function addOption(node: LGraphNode) {\n    if (!node.widgets) return\n    const newCount = node.widgets.length - 1\n    const widgetName = `option${newCount}`\n    const widget = node.addWidget('string', widgetName, '', () => {})\n    let localValue = `${widget.value ?? ''}`\n\n    Object.defineProperty(widget, 'value', {\n      get() {\n        return (\n          useWidgetValueStore().getWidget(\n            widgetId(app.rootGraph.id, node.id, widgetName)\n          )?.value ?? localValue\n        )\n      },\n      set(v: string) {\n        localValue = v\n        const state = useWidgetValueStore().getWidget(\n          widgetId(app.rootGraph.id, node.id, widgetName)\n        )\n        if (state) state.value = v\n        updateCombo()\n        if (!node.widgets) return\n        const lastWidget = node.widgets.at(-1)\n        if (lastWidget === this) {\n          if (v) addOption(node)\n          return\n        }\n        if (v || node.widgets.at(-2) !== this || lastWidget?.value) return\n        node.widgets.pop()\n        node.computeSize(node.size)\n        this.callback(v)\n      }\n    })\n  }\n  const widgets = this.widgets!\n  widgets.push({\n    name: 'index',\n    type: 'hidden',\n    get value() {\n      return widgets.slice(2).findIndex((w) => w.value === comboWidget.value)\n    },\n    set value(_) {},\n    draw: () => undefined,\n    hidden: true,\n    options: {},\n    y: 0,\n    serializeValue: (resolverNode: LGraphNode, _index: number) =>\n      widgets\n        .slice(2)\n        .findIndex(\n          (w) => w.value === resolveChoiceValue(this, comboWidget, resolverNode)\n        )\n  })\n  addOption(this)\n}\n\nclass StubWidget<T extends WidgetValue> extends BaseWidget {\n  override serialize = true\n  constructor(\n    node: LGraphNode,\n    name: string,\n    protected valueGetter: () => T\n  ) {\n    super({ name, node, options: { socketless: true }, type: 'hidden', y: 0 })\n  }\n  drawWidget() {}\n  onClick() {}\n  override get value(): T {\n    return this.valueGetter()\n  }\n  override set value(_: T) {}\n}\nfunction connectedInputsFor(node: LGraphNode, prefix: string = 'autogrow.') {\n  return computed(() =>\n    node.inputs\n      .filter((input) => input.name.startsWith(prefix) && input.link)\n      .map((input) => input.label ?? input.localized_name ?? input.name)\n  )\n}\n\nfunction onCustomIntCreated(this: LGraphNode) {\n  const valueWidget = this.widgets?.[0]\n  if (!valueWidget) return\n\n  Object.defineProperty(valueWidget.options, 'min', {\n    get: () => this.properties.min ?? -(2 ** 63),\n    set: (v) => {\n      this.properties.min = v\n      valueWidget.callback?.(valueWidget.value)\n    }\n  })\n  Object.defineProperty(valueWidget.options, 'max', {\n    get: () => this.properties.max ?? 2 ** 63,\n    set: (v) => {\n      this.properties.max = v\n      valueWidget.callback?.(valueWidget.value)\n    }\n  })\n  Object.defineProperty(valueWidget.options, 'step2', {\n    get: () => this.properties.step ?? 1,\n    set: (v) => {\n      this.properties.step = v\n      valueWidget.callback?.(valueWidget.value) // for vue reactivity\n    }\n  })\n}\nconst DISPLAY_WIDGET_TYPES = new Set(['gradientslider', 'slider', 'knob'])\n\nconst finiteNumber = (value: unknown) =>\n  typeof value === 'number' && Number.isFinite(value) ? value : undefined\n\nconst positiveNumber = (value: unknown) => {\n  const n = finiteNumber(value)\n  return n !== undefined && n > 0 ? n : undefined\n}\n\nconst fractionDigits = (value: unknown) => {\n  const n = finiteNumber(value)\n  return n === undefined ? undefined : clamp(Math.trunc(n), 0, 100)\n}\n\nconst lastDecimalPlace = (places: number) =>\n  Number((10 ** -places).toFixed(places))\n\nfunction onCustomFloatCreated(this: LGraphNode) {\n  const valueWidget = this.widgets?.[0]\n  if (!valueWidget) return\n\n  const declaredPrecision = fractionDigits(valueWidget.options.precision) ?? 1\n  const declaredStep =\n    positiveNumber(valueWidget.options.step2) ??\n    lastDecimalPlace(declaredPrecision)\n  const declaredRound = valueWidget.options.round\n  const declaresRounding = positiveNumber(declaredRound) !== undefined\n  const nodePrecision = () => fractionDigits(this.properties.precision)\n\n  let baseType = valueWidget.type\n  Object.defineProperty(valueWidget, 'type', {\n    get: () => {\n      const display = this.properties.display as string | undefined\n      if (display && DISPLAY_WIDGET_TYPES.has(display)) return display\n      return baseType\n    },\n    set: (v: string) => {\n      baseType = v\n    }\n  })\n\n  Object.defineProperty(valueWidget.options, 'gradient_stops', {\n    enumerable: true,\n    get: () => this.properties.gradient_stops,\n    set: (v) => {\n      this.properties.gradient_stops = v\n    }\n  })\n  Object.defineProperty(valueWidget.options, 'min', {\n    get: () => this.properties.min ?? -Infinity,\n    set: (v) => {\n      this.properties.min = v\n      valueWidget.callback?.(valueWidget.value)\n    }\n  })\n  Object.defineProperty(valueWidget.options, 'max', {\n    get: () => this.properties.max ?? Infinity,\n    set: (v) => {\n      this.properties.max = v\n      valueWidget.callback?.(valueWidget.value)\n    }\n  })\n  Object.defineProperty(valueWidget.options, 'precision', {\n    get: () => nodePrecision() ?? declaredPrecision,\n    set: (v) => {\n      this.properties.precision = v\n      valueWidget.callback?.(valueWidget.value)\n    }\n  })\n  Object.defineProperty(valueWidget.options, 'step2', {\n    get: () => {\n      const configured = positiveNumber(this.properties.step)\n      if (configured !== undefined) return configured\n      const places = nodePrecision()\n      return places === undefined ? declaredStep : lastDecimalPlace(places)\n    },\n    set: (v) => (this.properties.step = v)\n  })\n  Object.defineProperty(valueWidget.options, 'round', {\n    get: () => {\n      const configured = positiveNumber(this.properties.round)\n      if (configured !== undefined) return configured\n      const places = nodePrecision()\n      return places !== undefined && declaresRounding\n        ? lastDecimalPlace(places)\n        : declaredRound\n    },\n    set: (v) => {\n      this.properties.round = v\n      valueWidget.callback?.(valueWidget.value)\n    }\n  })\n}\n\napp.registerExtension({\n  name: 'Comfy.CustomWidgets',\n  beforeRegisterNodeDef(nodeType: typeof LGraphNode, nodeData: ComfyNodeDef) {\n    if (nodeData.name === 'CustomCombo')\n      nodeType.prototype.onNodeCreated = useChainCallback(\n        nodeType.prototype.onNodeCreated,\n        onCustomComboCreated\n      )\n    else if (nodeData.name === 'PrimitiveInt')\n      nodeType.prototype.onNodeCreated = useChainCallback(\n        nodeType.prototype.onNodeCreated,\n        onCustomIntCreated\n      )\n    else if (nodeData.name === 'PrimitiveFloat')\n      nodeType.prototype.onNodeCreated = useChainCallback(\n        nodeType.prototype.onNodeCreated,\n        onCustomFloatCreated\n      )\n  },\n  getCustomWidgets() {\n    return {\n      COMFY_BRANCH_INPUT_NAMES: function (node, inputName) {\n        const connectedInputs = connectedInputsFor(node)\n        const values = () => connectedInputs.value\n        node.addCustomWidget(new StubWidget<string[]>(node, inputName, values))\n      },\n      COMFY_BRANCH_SELECTOR: function (node, inputName) {\n        const connectedInputs = connectedInputsFor(node)\n        const values = () => connectedInputs.value\n        const startValue = connectedInputs.value[0] ?? ''\n        node.addWidget('combo', inputName, startValue, () => {}, { values })\n        node.onInputAdded = useChainCallback(node.onInputAdded, (input) => {\n          if (input.widget?.name !== inputName) return\n          input.widget[GET_CONFIG] = () => ['COMBO', { options: values }]\n        })\n      }\n    }\n  }\n})\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useExtensionService } from '@/services/extensionService'\nimport { processDynamicPrompt } from '@/utils/formatUtil'\n\n// Allows for simple dynamic prompt replacement\n// Inputs in the format {a|b} will have a random value of a or b chosen when the prompt is queued.\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.DynamicPrompts',\n  nodeCreated(node: LGraphNode) {\n    if (node.widgets) {\n      // Locate dynamic prompt text widgets\n      // Include any widgets with dynamicPrompts set to true, and customtext\n      const widgets = node.widgets.filter((w) => w.dynamicPrompts)\n      for (const widget of widgets) {\n        // Override the serialization of the value to resolve dynamic prompts for all widgets supporting it in this node\n        widget.serializeValue = (workflowNode, widgetIndex) => {\n          if (typeof widget.value !== 'string') return widget.value\n\n          const prompt = processDynamicPrompt(widget.value)\n\n          // Overwrite the value in the serialized workflow pnginfo\n          if (workflowNode?.widgets_values)\n            workflowNode.widgets_values[widgetIndex] = prompt\n\n          return prompt\n        }\n      }\n    }\n  }\n})\n","import { app } from '../../scripts/app'\n\ntype Enclosure = {\n  start: number\n  end: number\n}\n\nexport function incrementWeight(weight: string, delta: number): string {\n  const floatWeight = parseFloat(weight)\n  if (isNaN(floatWeight)) return weight\n  const newWeight = floatWeight + delta\n  return String(Number(newWeight.toFixed(10)))\n}\n\nexport function findNearestEnclosure(\n  text: string,\n  cursorPos: number\n): Enclosure | null {\n  let start = cursorPos\n  let end = cursorPos\n  let openCount = 0\n  let closeCount = 0\n\n  if (text[cursorPos] === '(') {\n    end = cursorPos + 1\n  } else {\n    while (start >= 0) {\n      start--\n      if (text[start] === '(' && openCount === closeCount) break\n      if (text[start] === '(') openCount++\n      if (text[start] === ')') closeCount++\n    }\n    if (start < 0) return null\n    openCount = 0\n    closeCount = 0\n  }\n\n  while (end < text.length) {\n    if (text[end] === ')' && openCount === closeCount) break\n    if (text[end] === '(') openCount++\n    if (text[end] === ')') closeCount++\n    end++\n  }\n  if (end === text.length) return null\n\n  return { start: start + 1, end: end }\n}\n\nexport function addWeightToParentheses(text: string): string {\n  const parenMatch = text.match(/^\\((.*)\\)$/)\n  if (!parenMatch) return text\n  const innerText = parenMatch[1]\n  // A time-like pattern (e.g. \"12:30\") is preceded by whitespace or string-start;\n  // everything else ending in \":number\" is a weight, including digit-ending names like \"v2:1.5\".\n  const looksLikeTime = /(?:^|\\s)\\d{1,2}:\\d{2}$/.test(innerText)\n  const hasTrailingWeight =\n    !looksLikeTime && /:[+-]?(?:\\d*\\.)?\\d+(?:[eE][+-]?\\d+)?$/.test(innerText)\n  return hasTrailingWeight ? text : `(${innerText}:1.0)`\n}\n\napp.registerExtension({\n  name: 'Comfy.EditAttention',\n  init() {\n    const editAttentionDelta = app.ui.settings.addSetting({\n      id: 'Comfy.EditAttention.Delta',\n      category: ['Comfy', 'EditTokenWeight', 'Delta'],\n      name: 'Ctrl+up/down precision',\n      type: 'slider',\n      attrs: {\n        min: 0.01,\n        max: 0.5,\n        step: 0.01\n      },\n      defaultValue: 0.05\n    })\n\n    function editAttention(event: KeyboardEvent) {\n      const inputField = event.composedPath()[0]\n      const delta = parseFloat(String(editAttentionDelta.value))\n\n      if (!(inputField instanceof HTMLTextAreaElement)) return\n      if (!(event.key === 'ArrowUp' || event.key === 'ArrowDown')) return\n      if (!event.ctrlKey && !event.metaKey) return\n\n      event.preventDefault()\n\n      let start = inputField.selectionStart\n      let end = inputField.selectionEnd\n      let selectedText = inputField.value.substring(start, end)\n\n      if (!selectedText) {\n        const nearestEnclosure = findNearestEnclosure(inputField.value, start)\n        if (nearestEnclosure) {\n          start = nearestEnclosure.start\n          end = nearestEnclosure.end\n          selectedText = inputField.value.substring(start, end)\n        } else {\n          const delimiters = ' .,\\\\/!?%^*;:{}=-_`~()\\r\\n\\t'\n\n          while (\n            !delimiters.includes(inputField.value[start - 1]) &&\n            start > 0\n          ) {\n            start--\n          }\n\n          while (\n            !delimiters.includes(inputField.value[end]) &&\n            end < inputField.value.length\n          ) {\n            end++\n          }\n\n          selectedText = inputField.value.substring(start, end)\n          if (!selectedText) return\n        }\n      }\n\n      const selectionEndsWithSpace =\n        selectedText[selectedText.length - 1] === ' '\n      if (selectionEndsWithSpace) {\n        selectedText = selectedText.substring(0, selectedText.length - 1)\n        end -= 1\n      }\n\n      const selectionIsSurroundedByParens =\n        inputField.value[start - 1] === '(' && inputField.value[end] === ')'\n      if (selectionIsSurroundedByParens) {\n        start -= 1\n        end += 1\n        selectedText = inputField.value.substring(start, end)\n      }\n\n      const selectionIsNotEnclosedInParens =\n        selectedText[0] !== '(' || selectedText[selectedText.length - 1] !== ')'\n      if (selectionIsNotEnclosedInParens) selectedText = `(${selectedText})`\n\n      selectedText = addWeightToParentheses(selectedText)\n\n      const weightDelta = event.key === 'ArrowUp' ? delta : -delta\n      const updatedText = selectedText.replace(\n        /\\((.*):([+-]?(?:\\d*\\.)?\\d+(?:[eE][+-]?\\d+)?)\\)/,\n        (_, text, weight) => {\n          weight = incrementWeight(weight, weightDelta)\n          if (weight == 1) {\n            return text\n          } else {\n            return `(${text}:${weight})`\n          }\n        }\n      )\n\n      inputField.setSelectionRange(start, end)\n      // Intentional use of deprecated: https://developer.mozilla.org/docs/Web/API/Document/execCommand#using_inserttext\n      document.execCommand('insertText', false, updatedText)\n      inputField.setSelectionRange(start, start + updatedText.length)\n    }\n    window.addEventListener('keydown', editAttention)\n  }\n})\n","/**\n * Constants for group node type prefixes and separators\n *\n * v1 Prefix + Separator: workflow/\n * v2 Prefix + Separator: workflow> (ComfyUI_frontend v1.2.63)\n */\nexport const PREFIX = 'workflow'\nexport const SEPARATOR = '>'\n","import type { PrimitiveNode } from '@/extensions/core/widgetInputs'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\nexport const isPrimitiveNode = (\n  node: LGraphNode\n): node is PrimitiveNode & LGraphNode => node.type === 'PrimitiveNode'\n","import { intersection, isNil, keys, union } from 'es-toolkit/compat'\n\nimport type {\n  ComboInputSpec,\n  ComboInputSpecV2,\n  FloatInputSpec,\n  InputSpec,\n  IntInputSpec,\n  NumericInputOptions\n} from '@/schemas/nodeDefSchema'\nimport {\n  getComboSpecComboOptions,\n  getInputSpecType,\n  isComboInputSpec,\n  isFloatInputSpec,\n  isIntInputSpec\n} from '@/schemas/nodeDefSchema'\n\nimport { lcm } from './mathUtil'\n\nconst IGNORE_KEYS = new Set<string>([\n  'default',\n  'forceInput',\n  'defaultInput',\n  'control_after_generate',\n  'multiline',\n  'tooltip',\n  'dynamicPrompts'\n])\n\nconst getRange = (options: Pick<NumericInputOptions, 'min' | 'max'>) => {\n  const min = options.min ?? -Infinity\n  const max = options.max ?? Infinity\n  return { min, max }\n}\n\nconst mergeNumericInputSpec = <T extends IntInputSpec | FloatInputSpec>(\n  spec1: T,\n  spec2: T\n): InputSpec | null => {\n  const type = spec1[0]\n  const options1 = spec1[1] ?? {}\n  const options2 = spec2[1] ?? {}\n\n  const range1 = getRange(options1)\n  const range2 = getRange(options2)\n\n  // If the ranges do not overlap, return null\n  if (range1.min > range2.max || range1.max < range2.min) {\n    return null\n  }\n\n  const step1 = options1.step ?? 1\n  const step2 = options2.step ?? 1\n\n  const mergedOptions = {\n    // Take intersection of ranges\n    min: Math.max(range1.min, range2.min),\n    max: Math.min(range1.max, range2.max),\n    step: lcm(step1, step2)\n  }\n\n  return mergeCommonInputSpec(\n    [type, { ...options1, ...mergedOptions }],\n    [type, { ...options2, ...mergedOptions }]\n  )\n}\n\nconst mergeComboInputSpec = <T extends ComboInputSpec | ComboInputSpecV2>(\n  spec1: T,\n  spec2: T\n): InputSpec | null => {\n  const options1 = spec1[1] ?? {}\n  const options2 = spec2[1] ?? {}\n\n  const comboOptions1 = getComboSpecComboOptions(spec1)\n  const comboOptions2 = getComboSpecComboOptions(spec2)\n\n  const commonOptions = intersection(comboOptions1, comboOptions2)\n\n  // If the intersection is empty, return null\n  if (commonOptions.length === 0) {\n    return null\n  }\n\n  return mergeCommonInputSpec(\n    ['COMBO', { ...options1, options: commonOptions }],\n    ['COMBO', { ...options2, options: commonOptions }]\n  )\n}\n\nconst mergeCommonInputSpec = <T extends InputSpec>(\n  spec1: T,\n  spec2: T\n): T | null => {\n  const type = getInputSpecType(spec1)\n  const options1 = spec1[1] ?? {}\n  const options2 = spec2[1] ?? {}\n\n  const compareKeys = union(keys(options1), keys(options2)).filter(\n    (key) => !IGNORE_KEYS.has(key)\n  )\n\n  const mergeIsValid = compareKeys.every((key) => {\n    const value1 = options1[key]\n    const value2 = options2[key]\n    return value1 === value2 || (isNil(value1) && isNil(value2))\n  })\n\n  return mergeIsValid ? ([type, { ...options1, ...options2 }] as T) : null\n}\n\n/**\n * Merges two input specs.\n *\n * @param spec1 - The first input spec.\n * @param spec2 - The second input spec.\n * @returns The merged input spec, or null if the specs are not mergeable.\n */\nexport const mergeInputSpec = (\n  spec1: InputSpec,\n  spec2: InputSpec\n): InputSpec | null => {\n  const type1 = getInputSpecType(spec1)\n  const type2 = getInputSpecType(spec2)\n\n  if (type1 !== type2) {\n    return null\n  }\n\n  if (isIntInputSpec(spec1) || isFloatInputSpec(spec1)) {\n    return mergeNumericInputSpec(spec1, spec2 as typeof spec1)\n  }\n\n  if (isComboInputSpec(spec1)) {\n    return mergeComboInputSpec(spec1, spec2 as typeof spec1)\n  }\n\n  return mergeCommonInputSpec(spec1, spec2)\n}\n","import { intersection } from 'es-toolkit/compat'\n\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { createWidgetRestorationState } from '@/lib/litegraph/src/LGraphNode'\nimport { LGraphNode, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type {\n  INodeInputSlot,\n  INodeOutputSlot,\n  ISerialisedNode,\n  ISlotType,\n  LLink\n} from '@/lib/litegraph/src/litegraph'\nimport type { IWidgetLocator } from '@/lib/litegraph/src/interfaces'\nimport { NodeSlot } from '@/lib/litegraph/src/node/NodeSlot'\nimport { outputHasLinks, outputLinks } from '@/lib/litegraph/src/node/slotLinks'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport { createAssetWidget } from '@/platform/assets/utils/createAssetWidget'\nimport {\n  getComboSpecComboOptions,\n  isComboInputSpec\n} from '@/schemas/nodeDefSchema'\nimport type { ComfyNodeDef, InputSpec } from '@/schemas/nodeDefSchema'\nimport { app } from '@/scripts/app'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport type { WidgetValue } from '@/types/simplifiedWidget'\nimport { addValueControlWidgets } from '@/core/graph/widgets/valueControlWidgets'\nimport { ComfyWidgets, isValidWidgetType } from '@/scripts/widgets'\nimport { isPrimitiveNode } from '@/renderer/utils/nodeTypeGuards'\nimport { CONFIG, GET_CONFIG } from '@/services/litegraphService'\nimport { mergeInputSpec } from '@/utils/nodeDefUtil'\nimport { applyTextReplacements } from '@/utils/searchAndReplace'\n\nimport { applyFirstWidgetValueToGraph } from './widgetValuePropagation'\n\nconst replacePropertyName = 'Run widget replace on values'\nexport class PrimitiveNode extends LGraphNode {\n  controlValues?: WidgetValue[]\n  lastType?: string\n  static override category: string\n  constructor(title: string) {\n    super(title)\n    this.addOutput('connect to widget input', '*')\n    this.serialize_widgets = true\n    this.isVirtualNode = true\n\n    if (!(replacePropertyName in this.properties)) {\n      this.addProperty(replacePropertyName, false, 'boolean')\n    }\n  }\n\n  override applyToGraph(extraLinks: LLink[] = []) {\n    const sourceWidget = this.widgets?.[0]\n    const graph = this.graph\n    if (!sourceWidget || !graph) return\n\n    let v = sourceWidget.value\n    if (v && this.properties[replacePropertyName]) {\n      v = applyTextReplacements(graph, v as string)\n    }\n    applyFirstWidgetValueToGraph(this, extraLinks, () => v)\n  }\n\n  override refreshComboInNode(defs?: Record<string, ComfyNodeDef>): void {\n    const widget = this.widgets?.[0]\n    if (widget?.type !== 'combo') return\n\n    const newValues = this._resolveComboValues(defs)\n    if (newValues === undefined) return\n\n    widget.options.values = newValues\n\n    const value = widget.value\n    if (\n      (typeof value !== 'string' && typeof value !== 'number') ||\n      !newValues.includes(value)\n    ) {\n      widget.value = newValues[0]\n      widget.callback?.(widget.value)\n    }\n  }\n\n  private _resolveComboValues(\n    defs?: Partial<Record<string, ComfyNodeDef>>\n  ): (string | number)[] | undefined {\n    const fromDefs = defs ? this._comboValuesFromDefs(defs) : undefined\n    if (fromDefs !== undefined) return fromDefs\n\n    const slotWidget = this.outputs[0].widget\n    const config = slotWidget?.[GET_CONFIG]?.()\n    if (!config || !isComboInputSpec(config)) return undefined\n\n    return getComboSpecComboOptions(config)\n  }\n\n  private _comboValuesFromDefs(\n    defs: Partial<Record<string, ComfyNodeDef>>\n  ): (string | number)[] | undefined {\n    const graph = this.graph\n    const links = graph ? outputLinks(graph, this.id, 0) : []\n    if (!graph || !links.length) return undefined\n\n    let values: (string | number)[] | undefined\n    for (const link of links) {\n      const targetNode = graph.getNodeById(link.target_id)\n      const targetType = targetNode?.type\n      const targetInput = targetNode?.inputs.at(link.target_slot)\n      const inputName = targetInput?.widget?.name ?? targetInput?.name\n      if (!targetType || !inputName) return undefined\n\n      const def = defs[targetType]\n      const inputSpec =\n        def?.input?.required?.[inputName] ?? def?.input?.optional?.[inputName]\n      if (!inputSpec || !isComboInputSpec(inputSpec)) return undefined\n\n      const options = getComboSpecComboOptions(inputSpec)\n      values = values === undefined ? options : intersection(values, options)\n    }\n\n    return values\n  }\n\n  override configure(serialisedNode: ISerialisedNode) {\n    const type = serialisedNode.outputs?.[0]?.type\n    super.configure(serialisedNode)\n    if (\n      !this.graph ||\n      this.widgets?.length ||\n      typeof type !== 'string' ||\n      !outputHasLinks(this.graph, this.id, 0)\n    )\n      return\n\n    useWidgetValueStore().setNodeWidgetRestoration(\n      this.graph.rootGraph.id,\n      this.id,\n      createWidgetRestorationState(serialisedNode)\n    )\n  }\n\n  override onAfterGraphConfigured() {\n    if (\n      this.graph &&\n      outputHasLinks(this.graph, this.id, 0) &&\n      !this.widgets?.length\n    ) {\n      this._onFirstConnection()\n\n      // Merge values if required\n      this._mergeWidgetConfig()\n    }\n  }\n\n  private _clearWidgetRestoration() {\n    if (this.graph)\n      useWidgetValueStore().clearNodeWidgetRestoration(\n        this.graph.rootGraph.id,\n        this.id\n      )\n  }\n\n  override onConnectionsChange(\n    _type: ISlotType,\n    _index: number,\n    connected: boolean\n  ) {\n    if (app.configuringGraph) {\n      // Dont run while the graph is still setting up\n      return\n    }\n\n    const hasLinks = this.graph ? outputHasLinks(this.graph, this.id, 0) : false\n    if (connected) {\n      if (hasLinks && !this.widgets?.length) {\n        this._onFirstConnection()\n      }\n    } else {\n      // We may have removed a link that caused the constraints to change\n      this._mergeWidgetConfig()\n\n      if (!hasLinks) {\n        this.onLastDisconnect()\n      }\n    }\n  }\n\n  override onConnectOutput(\n    slot: number,\n    _type: string,\n    input: INodeInputSlot,\n    target_node: LGraphNode,\n    target_slot: number\n  ) {\n    // Fires before the link is made allowing us to reject it if it isn't valid\n    // No widget, we can't connect\n    if (\n      !input.widget &&\n      (typeof input.type !== 'string' || !(input.type in ComfyWidgets))\n    ) {\n      return false\n    }\n\n    if (this.graph && outputHasLinks(this.graph, this.id, slot)) {\n      const valid = this._isValidConnection(input)\n      if (valid) {\n        // On connect of additional outputs, copy our value to their widget\n        this.applyToGraph([{ target_id: target_node.id, target_slot } as LLink])\n      }\n      return valid\n    }\n\n    return true\n  }\n\n  private _onFirstConnection(recreating = false) {\n    // First connection can fire before the graph is ready on initial load so random things can be missing\n    if (!this.graph) {\n      this.onLastDisconnect()\n      return\n    }\n    const link = outputLinks(this.graph, this.id, 0).at(0)\n    if (!link) {\n      if (outputHasLinks(this.graph, this.id, 0)) {\n        console.warn(\n          `PrimitiveNode ${this.id}: link store reports output 0 connected but no link resolves in the graph; resetting the widget.`\n        )\n      }\n      this.onLastDisconnect()\n      return\n    }\n\n    const theirNode = this.graph.getNodeById(link.target_id)\n    if (!theirNode) return\n\n    const input = theirNode.inputs.at(link.target_slot)\n    if (!input) return\n\n    let widget: IWidgetLocator\n    if (!input.widget) {\n      const inputType = input.type\n      if (typeof inputType !== 'string' || !(inputType in ComfyWidgets)) return\n      widget = { name: input.name, [GET_CONFIG]: () => [inputType, {}] } //fake widget\n    } else {\n      widget = input.widget\n    }\n\n    const config = widget[GET_CONFIG]?.()\n    if (!config) return\n\n    const { type } = getWidgetType(config)\n    if (recreating || this.outputs[0].type !== type)\n      this._clearWidgetRestoration()\n    // Update our output to restrict to the widget type\n    this.outputs[0].type = type\n    this.outputs[0].name = type\n    this.outputs[0].widget = widget\n\n    this._createWidget(\n      widget[CONFIG] ?? config,\n      theirNode,\n      widget.name,\n      recreating\n    )\n  }\n\n  private _createWidget(\n    inputData: InputSpec,\n    node: LGraphNode,\n    widgetName: string,\n    recreating: boolean\n  ) {\n    let type = inputData[0]\n\n    if (type instanceof Array) {\n      type = 'COMBO'\n    }\n\n    // Store current size as addWidget resizes the node\n    const [oldWidth, oldHeight] = this.size\n    let widget: IBaseWidget\n    const restoredValue = this.graph\n      ? useWidgetValueStore().getRestoredWidgetValue(\n          this.graph.rootGraph.id,\n          this.id,\n          'value',\n          0\n        )\n      : undefined\n\n    try {\n      if (\n        type === 'COMBO' &&\n        assetService.shouldUseWidgetAssetPicker(node.comfyClass, widgetName)\n      ) {\n        widget = this._createAssetWidget(node, widgetName, inputData)\n        const theirWidget = node.widgets?.find((w) => w.name === widgetName)\n        if (theirWidget) widget.value = theirWidget.value\n        if (restoredValue) widget.value = restoredValue.value\n        this._finalizeWidget(widget, oldWidth, oldHeight, recreating)\n        return\n      }\n\n      if (isValidWidgetType(type)) {\n        widget = ComfyWidgets[type](this, 'value', inputData, app).widget\n      } else {\n        widget = this.addCustomWidget({\n          type: type.toLowerCase(),\n          name: 'value',\n          value: null,\n          callback: () => {},\n          options: {},\n          y: 0\n        })\n      }\n\n      if (node.widgets) {\n        const theirWidget = node.widgets.find((w) => w.name === widgetName)\n        if (theirWidget) {\n          widget.value = theirWidget.value\n        }\n      }\n      if (restoredValue) widget.value = restoredValue.value\n\n      if (\n        !inputData[1]?.control_after_generate &&\n        (widget.type === 'number' || widget.type === 'combo')\n      ) {\n        addValueControlWidgets(this, widget, 'fixed', undefined, inputData)\n        if (this.widgets?.[1]) widget.linkedWidgets = [this.widgets[1]]\n      }\n\n      // Restore any saved control values\n      const controlValues = this.controlValues\n      if (\n        this.widgets &&\n        this.lastType === this.widgets[0]?.type &&\n        controlValues?.length === this.widgets.length - 1\n      ) {\n        for (let i = 0; i < controlValues.length; i++) {\n          this.widgets[i + 1].value = controlValues[i]\n        }\n      }\n\n      this._finalizeWidget(widget, oldWidth, oldHeight, recreating)\n    } finally {\n      this._clearWidgetRestoration()\n    }\n  }\n\n  private _createAssetWidget(\n    targetNode: LGraphNode,\n    targetInputName: string,\n    inputData: InputSpec\n  ): IBaseWidget {\n    const defaultValue = inputData[1]?.default as string | undefined\n    return createAssetWidget({\n      node: this,\n      widgetName: 'value',\n      nodeTypeForBrowser: targetNode.comfyClass ?? '',\n      inputNameForBrowser: targetInputName,\n      defaultValue\n    })\n  }\n\n  private _finalizeWidget(\n    widget: IBaseWidget,\n    oldWidth: number,\n    oldHeight: number,\n    recreating: boolean\n  ) {\n    widget.callback = useChainCallback(widget.callback, () => {\n      this.applyToGraph()\n    })\n\n    this.setSize([\n      Math.max(this.size[0], oldWidth),\n      Math.max(this.size[1], oldHeight)\n    ])\n\n    if (!recreating) {\n      const sz = this.computeSize()\n      this.size = [Math.max(this.size[0], sz[0]), Math.max(this.size[1], sz[1])]\n\n      requestAnimationFrame(() => {\n        this.onResize?.(this.size)\n      })\n    }\n  }\n\n  recreateWidget() {\n    const values = this.widgets?.map((w) => w.value)\n    this._removeWidgets()\n    this._onFirstConnection(!!values?.length)\n    if (values?.length && this.widgets) {\n      for (let i = 0; i < this.widgets.length; i++)\n        this.widgets[i].value = values[i]\n    }\n    return this.widgets?.[0]\n  }\n\n  private _mergeWidgetConfig() {\n    // Merge widget configs if the node has multiple outputs\n    const output = this.outputs[0]\n    const links = this.graph ? outputLinks(this.graph, this.id, 0) : []\n\n    const hasConfig = !!output.widget?.[CONFIG]\n    if (hasConfig) {\n      delete output.widget?.[CONFIG]\n    }\n\n    if (links.length < 2 && hasConfig) {\n      // Copy the widget options from the source\n      if (links.length) {\n        this.recreateWidget()\n      }\n\n      return\n    }\n    const config1 = output.widget?.[GET_CONFIG]?.()\n    if (!config1) return\n    const isNumber = config1[0] === 'INT' || config1[0] === 'FLOAT'\n    if (!isNumber || !this.graph) return\n\n    for (const link of links) {\n      const theirNode = this.graph.getNodeById(link.target_id)\n      if (!theirNode) continue\n      const theirInput = theirNode.inputs[link.target_slot]\n\n      // Call is valid connection so it can merge the configs when validating\n      this._isValidConnection(theirInput, hasConfig)\n    }\n  }\n\n  private _isValidConnection(input: INodeInputSlot, forceUpdate?: boolean) {\n    // Only allow connections where the configs match\n    const output = this.outputs[0]\n    const config2 = input.widget?.[GET_CONFIG]?.()\n    if (!config2) return false\n\n    return !!mergeIfValid(output, config2, forceUpdate, () =>\n      this.recreateWidget()\n    )\n  }\n\n  private _removeWidgets() {\n    if (this.widgets) {\n      // Allow widgets to cleanup\n      for (const w of this.widgets) {\n        if (w.onRemove) {\n          w.onRemove()\n        }\n      }\n\n      // Temporarily store the current values in case the node is being recreated\n      this.controlValues = []\n      this.lastType = this.widgets[0]?.type\n      for (let i = 1; i < this.widgets.length; i++) {\n        this.controlValues.push(this.widgets[i].value)\n      }\n      setTimeout(() => {\n        delete this.lastType\n        delete this.controlValues\n      }, 15)\n      this.widgets.length = 0\n    }\n  }\n\n  onLastDisconnect() {\n    this._clearWidgetRestoration()\n    // We can't remove + re-add the output here as if you drag a link over the same link\n    // it removes, then re-adds, causing it to break\n    this.outputs[0].type = '*'\n    this.outputs[0].name = 'connect to widget input'\n    delete this.outputs[0].widget\n\n    this._removeWidgets()\n  }\n}\n\nexport function getWidgetConfig(\n  slot: Pick<INodeInputSlot | INodeOutputSlot, 'widget'>\n): InputSpec {\n  return slot.widget?.[CONFIG] ?? slot.widget?.[GET_CONFIG]?.() ?? ['*', {}]\n}\n\nfunction getConfig(this: LGraphNode, widgetName: string) {\n  const { nodeData } = this.constructor\n  return (\n    nodeData?.input?.required?.[widgetName] ??\n    nodeData?.input?.optional?.[widgetName]\n  )\n}\n\n/**\n * Convert a widget to an input slot.\n * @deprecated Widget to socket conversion is no longer necessary, as they co-exist now.\n * @param node The node to convert the widget to an input slot for.\n * @param widget The widget to convert to an input slot.\n * @returns The input slot that was converted from the widget or undefined if the widget is not found.\n */\nexport function convertToInput(\n  node: LGraphNode,\n  widget: IBaseWidget\n): INodeInputSlot | undefined {\n  console.warn(\n    'Please remove call to convertToInput. Widget to socket conversion is no longer necessary, as they co-exist now.'\n  )\n  return node.inputs.find((slot) => slot.widget?.name === widget.name)\n}\n\nfunction getWidgetType(config: InputSpec) {\n  // Special handling for COMBO so we restrict links based on the entries\n  let type = config[0]\n  if (type instanceof Array) {\n    type = 'COMBO'\n  }\n  return { type }\n}\n\nexport function setWidgetConfig(slot: INodeInputSlot, config?: InputSpec) {\n  if (!slot.widget) return\n  if (config) {\n    slot.widget[GET_CONFIG] = () => config\n  } else {\n    delete slot.widget\n  }\n\n  if (!(slot instanceof NodeSlot)) return\n  const { node } = slot\n  if (!node.graph) return\n  const link = node.getInputLink(node.inputs.indexOf(slot))\n  if (!link) return\n  const originNode = node.graph.getNodeById(link.origin_id)\n  if (!originNode || !isPrimitiveNode(originNode)) return\n  if (config) {\n    originNode.recreateWidget()\n  } else if (!app.configuringGraph) {\n    originNode.disconnectOutput(0)\n    originNode.onLastDisconnect()\n  }\n}\n\nexport function mergeIfValid(\n  output: Pick<INodeOutputSlot | INodeInputSlot, 'widget'>,\n  config2: InputSpec,\n  forceUpdate?: boolean,\n  recreateWidget?: () => IBaseWidget | undefined | void,\n  config1?: InputSpec\n): { customConfig: InputSpec[1] } {\n  if (!config1) {\n    config1 = getWidgetConfig(output)\n  }\n\n  const customSpec = mergeInputSpec(config1, config2)\n\n  if (customSpec || forceUpdate) {\n    if (customSpec) {\n      if (output.widget) output.widget[CONFIG] = customSpec\n    }\n\n    const widget = recreateWidget?.()\n    // When deleting a node this can be null\n    if (widget) {\n      const { min, max } = widget.options\n      if (typeof widget.value === 'number') {\n        if (min != null && widget.value < min) widget.value = min\n        if (max != null && widget.value > max) widget.value = max\n      }\n      widget.callback?.(widget.value)\n    }\n  }\n\n  return { customConfig: customSpec?.[1] ?? {} }\n}\n\napp.registerExtension({\n  name: 'Comfy.WidgetInputs',\n  async beforeRegisterNodeDef(\n    nodeType: typeof LGraphNode,\n    _nodeData: ComfyNodeDef\n  ) {\n    nodeType.prototype.convertWidgetToInput = function (this: LGraphNode) {\n      console.warn(\n        'Please remove call to convertWidgetToInput. Widget to socket conversion is no longer necessary, as they co-exist now.'\n      )\n      return false\n    }\n\n    nodeType.prototype.onGraphConfigured = useChainCallback(\n      nodeType.prototype.onGraphConfigured,\n      function (this: LGraphNode) {\n        this.widgets ??= []\n\n        for (const input of this.inputs) {\n          if (input.widget) {\n            const name = input.widget.name\n            if (!input.widget[GET_CONFIG]) {\n              input.widget[GET_CONFIG] = () => getConfig.call(this, name)\n            }\n\n            const w = this.widgets.find((w) => w.name === name)\n            if (!w) {\n              this.removeInput(this.inputs.findIndex((i) => i === input))\n            }\n          }\n        }\n      }\n    )\n\n    nodeType.prototype.onConfigure = useChainCallback(\n      nodeType.prototype.onConfigure,\n      function (this: LGraphNode) {\n        if (!app.configuringGraph) {\n          // On copy + paste of nodes, ensure that widget configs are set up\n          for (const input of this.inputs) {\n            if (input.widget && !input.widget[GET_CONFIG]) {\n              const name = input.widget.name\n              input.widget[GET_CONFIG] = () => getConfig.call(this, name)\n            }\n          }\n        }\n      }\n    )\n\n    // Double click a widget input to automatically attach a primitive\n    const origOnInputDblClick = nodeType.prototype.onInputDblClick\n    nodeType.prototype.onInputDblClick = function (\n      this: LGraphNode,\n      ...[slot, ...args]: Parameters<NonNullable<typeof origOnInputDblClick>>\n    ) {\n      const r = origOnInputDblClick?.apply(this, [slot, ...args])\n\n      const input = this.inputs[slot]\n      if (!input.widget) {\n        // Not a widget input or already handled input\n        if (typeof input.type !== 'string' || !(input.type in ComfyWidgets)) {\n          return r //also Not a ComfyWidgets input or combo (do nothing)\n        }\n      }\n\n      // Create a primitive node\n      const node = LiteGraph.createNode('PrimitiveNode')\n      const graph = app.canvas.graph\n      if (!node || !graph) return r\n\n      graph.add(node)\n\n      // Calculate a position that won't directly overlap another node\n      const pos: [number, number] = [\n        this.pos[0] - node.size[0] - 30,\n        this.pos[1]\n      ]\n      while (graph.getNodeOnPos(pos[0], pos[1], graph.nodes))\n        pos[1] += LiteGraph.NODE_TITLE_HEIGHT\n\n      node.pos = pos\n      node.connect(0, this, slot)\n      node.title = input.name\n\n      return r\n    }\n  },\n  registerCustomNodes() {\n    LiteGraph.registerNodeType(\n      'PrimitiveNode',\n      Object.assign(PrimitiveNode, {\n        title: 'Primitive'\n      })\n    )\n    PrimitiveNode.category = 'utilities/primitive'\n  }\n})\n","import { PREFIX, SEPARATOR } from '@/constants/groupNodeConstants'\nimport { t } from '@/i18n'\nimport type { ISlotType } from '@/lib/litegraph/src/interfaces'\nimport type { ISerialisedNode } from '@/lib/litegraph/src/types/serialisation'\nimport type {\n  LGraphNodeConstructor,\n  LGraphNode\n} from '@/lib/litegraph/src/litegraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { outputLinks } from '@/lib/litegraph/src/node/slotLinks'\nimport { slotTypeKey } from '@/lib/litegraph/src/utils/type'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport { parseNodeId } from '@/types/nodeId'\nimport type {\n  ComfyNode,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport type {\n  ComfyNodeDef,\n  ComfyOutputTypesSpec,\n  InputSpec\n} from '@/schemas/nodeDefSchema'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useWidgetStore } from '@/stores/widgetStore'\nimport type { ComfyExtension } from '@/types/comfy'\nimport { deserialiseAndCreate } from '@/utils/vintageClipboard'\n\nimport { app } from '../../scripts/app'\nimport { mergeIfValid } from './widgetInputs'\n\n/**\n * Marker symbol stamped on a synthesized group-node type's `nodeData` (via\n * {@link markGroupNodeType}) so loaded group-node instances can be detected and\n * migrated to subgraphs.\n */\nconst GROUP = Symbol()\n\n/**\n * Stamp the group-node marker onto the registered node type so instances created\n * during load can be detected by {@link GroupNodeHandler.isGroupNode}. This is\n * stamped directly on the constructor rather than copied through\n * {@link ComfyNodeDefImpl} construction, keeping the migration self-contained.\n */\nfunction markGroupNodeType(typeName: string, config: GroupNodeConfig): void {\n  const ctor = LiteGraph.registered_node_types[typeName] as\n    | LGraphNodeConstructor\n    | undefined\n  if (ctor?.nodeData) ctor.nodeData[GROUP] = config\n}\n\n/**\n * Link stored in a group node's workflow data. `sourceNodeIndex` is `null` when\n * the source node was outside the group when it was created.\n */\nexport type GroupNodeLink = [\n  sourceNodeIndex: number | null,\n  sourceSlot: number,\n  targetNodeIndex: number,\n  targetSlot: number,\n  sourceNodeId: SerializedNodeId,\n  type?: unknown\n]\ntype SlotLinks = Partial<Record<number, GroupNodeLink>>\ntype LinksFromMap = Partial<\n  Record<number, Partial<Record<number, GroupNodeLink[]>>>\n>\n\nfunction isSlotType(value: unknown): value is ISlotType {\n  return (\n    typeof value === 'number' ||\n    typeof value === 'string' ||\n    (Array.isArray(value) && value.every((item) => typeof item === 'string'))\n  )\n}\ntype LinksToMap = Partial<Record<number, SlotLinks>>\ntype ExternalFromMap = Partial<\n  Record<number, Partial<Record<number, string | number>>>\n>\n\ninterface GroupNodeConfigEntry {\n  input?: Record<string, { name?: string; visible?: boolean }>\n  output?: Record<number, { name?: string; visible?: boolean }>\n}\n\ninterface GroupNodeData extends Partial<\n  Pick<\n    ISerialisedNode,\n    'type' | 'title' | 'inputs' | 'outputs' | 'widgets_values'\n  >\n> {\n  index?: number\n}\n\nexport interface GroupNodeWorkflowData {\n  external?: (number | string)[][]\n  links: GroupNodeLink[]\n  nodes: GroupNodeData[]\n  config?: Record<number, GroupNodeConfigEntry>\n}\n\nfunction isOutputTypeSpec(\n  value: unknown\n): value is ComfyOutputTypesSpec[number] {\n  return (\n    typeof value === 'string' ||\n    (Array.isArray(value) &&\n      value.every(\n        (option) => typeof option === 'string' || typeof option === 'number'\n      ))\n  )\n}\n\ninterface GroupNodeDef {\n  input: {\n    required: Record<string, unknown>\n    optional?: Record<string, unknown>\n  }\n  output: unknown[]\n  output_name: string[]\n  output_is_list: boolean[]\n}\n\nexport class GroupNodeConfig {\n  name: string\n  nodeData: GroupNodeWorkflowData\n  inputCount: number\n  oldToNewOutputMap: Partial<Record<number, Record<number, number>>>\n  newToOldOutputMap: Partial<\n    Record<number, { node: GroupNodeData; slot: number }>\n  >\n  oldToNewInputMap: Partial<Record<number, Record<string, number>>>\n  oldToNewWidgetMap: Partial<Record<number, Record<string, string | null>>>\n  newToOldWidgetMap: Record<string, { node: GroupNodeData; inputName: string }>\n  primitiveDefs: Partial<Record<number, GroupNodeDef>>\n  widgetToPrimitive: Partial<Record<number, Record<string, number | number[]>>>\n  primitiveToWidget: Partial<\n    Record<number, { nodeId: number | string | null; inputName: string }[]>\n  >\n  nodeInputs: Partial<Record<number, Record<string, string>>>\n  outputVisibility: boolean[]\n  nodeDef: ComfyNodeDef | undefined\n  inputs!: unknown[]\n  linksFrom!: LinksFromMap\n  linksTo!: LinksToMap\n  externalFrom!: ExternalFromMap\n\n  constructor(name: string, nodeData: GroupNodeWorkflowData) {\n    this.name = name\n    this.nodeData = nodeData\n    this.getLinks()\n\n    this.inputCount = 0\n    this.oldToNewOutputMap = {}\n    this.newToOldOutputMap = {}\n    this.oldToNewInputMap = {}\n    this.oldToNewWidgetMap = {}\n    this.newToOldWidgetMap = {}\n    this.primitiveDefs = {}\n    this.widgetToPrimitive = {}\n    this.primitiveToWidget = {}\n    this.nodeInputs = {}\n    this.outputVisibility = []\n  }\n\n  async registerType(source = PREFIX) {\n    this.nodeDef = {\n      output: [],\n      output_name: [],\n      output_is_list: [],\n      output_node: false, // This is a lie (to satisfy the interface)\n      name: source + SEPARATOR + this.name,\n      display_name: this.name,\n      category: 'group nodes' + (SEPARATOR + source),\n      input: { required: {} },\n      description: `Group node combining ${this.nodeData.nodes\n        .map((n) => n.type)\n        .join(', ')}`,\n      python_module: 'custom_nodes.' + this.name\n    }\n\n    this.inputs = []\n    const seenInputs = {}\n    const seenOutputs = {}\n    for (let i = 0; i < this.nodeData.nodes.length; i++) {\n      const node = this.nodeData.nodes[i]\n      node.index = i\n      this.processNode(node, seenInputs, seenOutputs)\n    }\n\n    for (const p of this._convertedToProcess) {\n      p()\n    }\n    this._convertedToProcess = []\n    const typeName = `${PREFIX}${SEPARATOR}${this.name}`\n    await app.registerNodeDef(typeName, this.nodeDef)\n    markGroupNodeType(typeName, this)\n    useNodeDefStore().addNodeDef(this.nodeDef)\n  }\n\n  getLinks() {\n    this.linksFrom = {}\n    this.linksTo = {}\n    this.externalFrom = {}\n\n    // Extract links for easy lookup\n    for (const link of this.nodeData.links) {\n      const [sourceNodeIndex, sourceSlot, targetNodeIndex, targetSlot] = link\n\n      // Skip links outside the copy config\n      if (sourceNodeIndex == null) continue\n\n      const fromSlots = (this.linksFrom[sourceNodeIndex] ??= {})\n      ;(fromSlots[sourceSlot] ??= []).push(link)\n      ;(this.linksTo[targetNodeIndex] ??= {})[targetSlot] = link\n    }\n\n    for (const ext of this.nodeData.external ?? []) {\n      const nodeIdx = Number(ext[0])\n      const slotIdx = Number(ext[1])\n      const typeVal = ext.at(2)\n      if (typeVal == null) continue\n      ;(this.externalFrom[nodeIdx] ??= {})[slotIdx] = typeVal\n    }\n  }\n\n  processNode(\n    node: GroupNodeData,\n    seenInputs: Record<string, number>,\n    seenOutputs: Record<string, number>\n  ) {\n    const def = this.getNodeDef(node)\n    if (!def) return\n\n    const inputs = { ...def.input?.required, ...def.input?.optional }\n\n    this.inputs.push(this.processNodeInputs(node, seenInputs, inputs))\n    if (def.output?.length) this.processNodeOutputs(node, seenOutputs, def)\n  }\n\n  getNodeDef(\n    node: GroupNodeData\n  ): GroupNodeDef | ComfyNodeDef | null | undefined {\n    if (node.type) {\n      const def = globalDefs[node.type]\n      if (def) return def\n    }\n\n    const nodeIndex = node.index\n    if (nodeIndex == null) return undefined\n\n    const linksFrom = this.linksFrom[nodeIndex]\n    if (node.type === 'PrimitiveNode') {\n      // Skip as its not linked\n      if (!linksFrom) return\n\n      const firstLink = linksFrom[0]?.at(0)\n      const linkedType: unknown = firstLink?.at(5)\n      let type: string | number | null = firstLink\n        ? linkedType == null\n          ? null\n          : isSlotType(linkedType)\n            ? slotTypeKey(linkedType)\n            : null\n        : null\n      if (type === 'COMBO') {\n        // Use the array items\n        const output = node.outputs?.[0]\n        const source = output?.widget?.name\n        const nodeIdx = firstLink?.[2]\n        if (source && nodeIdx != null) {\n          const fromTypeName = this.nodeData.nodes.at(nodeIdx)?.type\n          if (fromTypeName) {\n            const fromType = globalDefs[fromTypeName]\n            const input =\n              fromType?.input?.required?.[source] ??\n              fromType?.input?.optional?.[source]\n            const inputType = input?.[0]\n            type =\n              typeof inputType === 'string' || typeof inputType === 'number'\n                ? inputType\n                : null\n          }\n        }\n      }\n\n      const def = (this.primitiveDefs[nodeIndex] = {\n        input: {\n          required: {\n            value: [type, {}]\n          }\n        },\n        output: [type],\n        output_name: [],\n        output_is_list: []\n      })\n      return def\n    } else if (node.type === 'Reroute') {\n      const linksTo = this.linksTo[nodeIndex]\n      if (linksTo && linksFrom && !this.externalFrom[nodeIndex]?.[0]) {\n        // Being used internally\n        return null\n      }\n\n      let config: Record<string, unknown> = {}\n      let rerouteType: ISlotType = '*'\n      if (linksFrom) {\n        const links = linksFrom[0] ?? []\n        for (const [, , targetNodeIndex, targetSlot] of links) {\n          const targetNode = this.nodeData.nodes.at(targetNodeIndex)\n          const input = targetNode?.inputs?.[targetSlot]\n          if (input?.type && rerouteType === '*') {\n            rerouteType = input.type\n          }\n          if (input?.widget && targetNode?.type) {\n            const targetDef = globalDefs[targetNode.type]\n            const targetWidget =\n              targetDef?.input?.required?.[input.widget.name] ??\n              targetDef?.input?.optional?.[input.widget.name]\n\n            if (targetWidget) {\n              const widgetSpec = [targetWidget[0], config] as Parameters<\n                typeof mergeIfValid\n              >[4]\n              const res = mergeIfValid(\n                { widget: widgetSpec } as unknown as Parameters<\n                  typeof mergeIfValid\n                >[0],\n                targetWidget,\n                false,\n                undefined,\n                widgetSpec\n              )\n              config = res.customConfig ?? config\n            }\n          }\n        }\n      } else if (linksTo) {\n        const link = linksTo[0]\n        if (link?.[0] != null) {\n          const output = this.nodeData.nodes.at(link[0])?.outputs?.[link[1]]\n          if (output) rerouteType = output.type\n        }\n      } else {\n        // Reroute used as a pipe\n        for (const l of this.nodeData.links) {\n          if (l[2] === node.index && isSlotType(l[5])) {\n            rerouteType = l[5]\n            break\n          }\n        }\n        if (rerouteType === '*') {\n          // Check for an external link\n          const t = this.externalFrom[nodeIndex]?.[0]\n          if (t) {\n            rerouteType = t\n          }\n        }\n      }\n\n      config.forceInput = true\n      const rerouteTypeKey = slotTypeKey(rerouteType)\n      return {\n        input: {\n          required: {\n            [rerouteTypeKey]: [rerouteTypeKey, config]\n          }\n        },\n        output: [rerouteTypeKey],\n        output_name: [],\n        output_is_list: []\n      }\n    }\n\n    console.warn(\n      'Skipping virtual node ' +\n        node.type +\n        ' when building group node ' +\n        this.name\n    )\n  }\n\n  getInputConfig(\n    node: GroupNodeData,\n    inputName: string,\n    seenInputs: Record<string, number>,\n    config: InputSpec,\n    extra?: Record<string, unknown>\n  ) {\n    const nodeConfig = this.nodeData.config?.[node.index ?? -1]\n    const customConfig = nodeConfig?.input?.[inputName]\n    let name =\n      customConfig?.name ??\n      node.inputs?.find((inp) => inp.name === inputName)?.label ??\n      inputName\n    let key = name\n    let prefix = ''\n    // Special handling for primitive to include the title if it is set rather than just \"value\"\n    if ((node.type === 'PrimitiveNode' && node.title) || name in seenInputs) {\n      prefix = `${node.title ?? node.type} `\n      key = name = `${prefix}${inputName}`\n      if (name in seenInputs) {\n        name = `${prefix}${seenInputs[name]} ${inputName}`\n      }\n    }\n    seenInputs[key] = (seenInputs[key] ?? 1) + 1\n\n    if (inputName === 'seed' || inputName === 'noise_seed') {\n      if (!extra) extra = {}\n      extra.control_after_generate = `${prefix}control_after_generate`\n    }\n    if (config[0] === 'IMAGEUPLOAD') {\n      if (!extra) extra = {}\n      const nodeIndex = node.index ?? -1\n      const configOptions = config[1] ?? {}\n      const widgetKey =\n        'widget' in configOptions && typeof configOptions.widget === 'string'\n          ? configOptions.widget\n          : 'image'\n      extra.widget = this.oldToNewWidgetMap[nodeIndex]?.[widgetKey] ?? 'image'\n    }\n\n    if (extra) {\n      config = [config[0], { ...config[1], ...extra }]\n    }\n\n    return { name, config, customConfig }\n  }\n\n  processWidgetInputs(\n    inputs: Record<string, unknown>,\n    node: GroupNodeData,\n    inputNames: string[],\n    seenInputs: Record<string, number>\n  ) {\n    const slots: string[] = []\n    const converted = new Map<number, string>()\n    const nodeIndex = node.index ?? -1\n    const widgetMap: Record<string, string | null> = (this.oldToNewWidgetMap[\n      nodeIndex\n    ] = {})\n    for (const inputName of inputNames) {\n      const inputSpec = inputs[inputName]\n      // The type is either a string (e.g. 'INT') or, for a combo widget, an\n      // array of options (e.g. [['euler', 'ddim']]) — both are valid V1\n      // input specs. Rejecting the array form here misclassified every combo\n      // widget as a plain input slot.\n      const isValidSpec =\n        Array.isArray(inputSpec) &&\n        inputSpec.length >= 1 &&\n        (typeof inputSpec[0] === 'string' || Array.isArray(inputSpec[0]))\n      // A `forceInput` spec is always a socket, even for a type (e.g. a\n      // combo) that would otherwise materialize as a widget — matches the\n      // rule `litegraphService.addInputSocket`/`addInputWidget` apply when\n      // actually building the node.\n      const specOptions =\n        Array.isArray(inputSpec) &&\n        typeof inputSpec[1] === 'object' &&\n        inputSpec[1] !== null\n          ? inputSpec[1]\n          : {}\n      const isForcedInput =\n        'forceInput' in specOptions && specOptions.forceInput === true\n      if (\n        isValidSpec &&\n        !isForcedInput &&\n        useWidgetStore().inputIsWidget(inputSpec as InputSpec)\n      ) {\n        const convertedIndex =\n          node.inputs?.findIndex(\n            (inp) => inp.name === inputName && inp.widget?.name === inputName\n          ) ?? -1\n        if (convertedIndex > -1) {\n          // This widget has been converted to a widget\n          // We need to store this in the correct position so link ids line up\n          converted.set(convertedIndex, inputName)\n          widgetMap[inputName] = null\n        } else {\n          // Normal widget\n          const { name, config } = this.getInputConfig(\n            node,\n            inputName,\n            seenInputs,\n            inputSpec as InputSpec\n          )\n          if (this.nodeDef?.input?.required) {\n            this.nodeDef.input.required[name] = config\n          }\n          widgetMap[inputName] = name\n          this.newToOldWidgetMap[name] = { node, inputName }\n        }\n      } else {\n        // Normal input\n        slots.push(inputName)\n      }\n    }\n    return { converted, slots }\n  }\n\n  checkPrimitiveConnection(\n    link: GroupNodeLink,\n    inputName: string,\n    inputs: Record<string, InputSpec>\n  ) {\n    const [sourceNodeIndex, , targetNodeIndex] = link\n    if (sourceNodeIndex == null) return\n    const sourceNode = this.nodeData.nodes.at(sourceNodeIndex)\n    if (sourceNode?.type === 'PrimitiveNode') {\n      // Merge link configurations\n      const primitiveDef = this.primitiveDefs[sourceNodeIndex]\n      if (!primitiveDef) return\n      const targetWidget = inputs[inputName]\n      const primitiveConfig = primitiveDef.input.required.value as [\n        unknown,\n        Record<string, unknown>\n      ]\n      const config = mergeIfValid(\n        {},\n        targetWidget,\n        false,\n        undefined,\n        primitiveConfig as InputSpec\n      )\n      const inputConfig = inputs[inputName]?.[1]\n      primitiveConfig[1] =\n        (config.customConfig ?? inputConfig)\n          ? { ...(typeof inputConfig === 'object' ? inputConfig : {}) }\n          : {}\n\n      const widgetName = this.oldToNewWidgetMap[sourceNodeIndex]?.['value']\n      if (widgetName) {\n        const name = widgetName.substring(0, widgetName.length - 6)\n        primitiveConfig[1].control_after_generate = true\n        primitiveConfig[1].control_prefix = name\n      }\n\n      const toPrimitive = (this.widgetToPrimitive[targetNodeIndex] ??= {})\n      const existing = toPrimitive[inputName]\n      if (Array.isArray(existing)) {\n        existing.push(sourceNodeIndex)\n      } else if (typeof existing === 'number') {\n        toPrimitive[inputName] = [existing, sourceNodeIndex]\n      } else {\n        toPrimitive[inputName] = sourceNodeIndex\n      }\n\n      ;(this.primitiveToWidget[sourceNodeIndex] ??= []).push({\n        nodeId: targetNodeIndex,\n        inputName\n      })\n    }\n  }\n\n  processInputSlots(\n    inputs: Record<string, InputSpec>,\n    node: GroupNodeData,\n    slots: string[],\n    linksTo: SlotLinks,\n    inputMap: Record<string, number>,\n    seenInputs: Record<string, number>\n  ) {\n    const nodeIdx = node.index ?? -1\n    const nodeInputs: Record<string, string> = (this.nodeInputs[nodeIdx] = {})\n    for (let i = 0; i < slots.length; i++) {\n      const inputName = slots[i]\n      // `linksTo` is keyed by this inner node's own original input-slot\n      // index, which rarely lines up with `i` (this input's position within\n      // the *filtered* `slots` list). Look the real slot index up by name so\n      // an internally-linked input isn't matched against a different slot's\n      // link (or missed/misread entirely) and either wrongly hidden or\n      // wrongly exposed on the group node. A synthesized def can key its\n      // input by type rather than by slot name (e.g. Reroute, whose actual\n      // slot name is always ''), so fall back to the old positional index\n      // when the name lookup misses.\n      const namedSlotIndex = node.inputs?.findIndex(\n        (inp) => inp.name === inputName\n      )\n      const slotIndex =\n        namedSlotIndex != null && namedSlotIndex >= 0 ? namedSlotIndex : i\n      const link = linksTo[slotIndex]\n      if (link) {\n        this.checkPrimitiveConnection(link, inputName, inputs)\n        // This input is linked so we can skip it\n        continue\n      }\n\n      const { name, config, customConfig } = this.getInputConfig(\n        node,\n        inputName,\n        seenInputs,\n        inputs[inputName]\n      )\n\n      nodeInputs[inputName] = name\n      if (customConfig?.visible === false) continue\n\n      if (this.nodeDef?.input?.required) {\n        this.nodeDef.input.required[name] = config\n      }\n      inputMap[inputName] = this.inputCount++\n    }\n  }\n\n  processConvertedWidgets(\n    inputs: Record<string, InputSpec>,\n    node: GroupNodeData,\n    converted: Map<number, string>,\n    linksTo: SlotLinks,\n    inputMap: Record<string, number>,\n    seenInputs: Record<string, number>\n  ) {\n    // Process converted widgets sorted into their index order (ordered as\n    // they were converted) so link ids match up. `converted`'s keys are\n    // this node's real serialized input-slot indices (set by the\n    // `findIndex` in processWidgetInputs), so use that key - not this\n    // widget's position among converted widgets - to look its link up in\n    // `linksTo`, which is also keyed by real slot index.\n    const convertedEntries = [...converted.entries()].sort(([a], [b]) => a - b)\n    for (const [slotIndex, inputName] of convertedEntries) {\n      if (!inputName) continue\n      const link = linksTo[slotIndex]\n      if (link) {\n        this.checkPrimitiveConnection(link, inputName, inputs)\n        // This input is linked so we can skip it\n        continue\n      }\n\n      const { name, config } = this.getInputConfig(\n        node,\n        inputName,\n        seenInputs,\n        inputs[inputName],\n        {\n          defaultInput: true\n        }\n      )\n\n      if (this.nodeDef?.input?.required) {\n        this.nodeDef.input.required[name] = config\n      }\n      this.newToOldWidgetMap[name] = { node, inputName }\n\n      const nodeIndex = node.index ?? -1\n      ;(this.oldToNewWidgetMap[nodeIndex] ??= {})[inputName] = name\n\n      inputMap[inputName] = this.inputCount++\n    }\n  }\n\n  private _convertedToProcess: (() => void)[] = []\n  processNodeInputs(\n    node: GroupNodeData,\n    seenInputs: Record<string, number>,\n    inputs: Record<string, unknown>\n  ) {\n    const inputMapping: unknown[] = []\n\n    const inputNames = Object.keys(inputs)\n    if (!inputNames.length) return\n\n    const { converted, slots } = this.processWidgetInputs(\n      inputs,\n      node,\n      inputNames,\n      seenInputs\n    )\n    const nodeIndex = node.index ?? -1\n    const linksTo = this.linksTo[nodeIndex] ?? {}\n    const inputMap: Record<string, number> = (this.oldToNewInputMap[nodeIndex] =\n      {})\n    this.processInputSlots(\n      inputs as Record<string, InputSpec>,\n      node,\n      slots,\n      linksTo,\n      inputMap,\n      seenInputs\n    )\n\n    // Converted inputs have to be processed after all other nodes as they'll be at the end of the list\n    this._convertedToProcess.push(() =>\n      this.processConvertedWidgets(\n        inputs as Record<string, InputSpec>,\n        node,\n        converted,\n        linksTo,\n        inputMap,\n        seenInputs\n      )\n    )\n\n    return inputMapping\n  }\n\n  processNodeOutputs(\n    node: GroupNodeData,\n    seenOutputs: Record<string, number>,\n    def: GroupNodeDef | ComfyNodeDef\n  ) {\n    const nodeIndex = node.index ?? -1\n    const oldToNew: Record<number, number> = (this.oldToNewOutputMap[\n      nodeIndex\n    ] = {})\n\n    const defOutput = def.output ?? []\n    // Add outputs\n    for (let outputId = 0; outputId < defOutput.length; outputId++) {\n      const linksFrom = this.linksFrom[nodeIndex]\n      // If this output is linked internally we flag it to hide\n      const hasLink =\n        linksFrom?.[outputId] && !this.externalFrom[nodeIndex]?.[outputId]\n      const outputConfig = this.nodeData.config?.[node.index ?? -1]\n      const customConfig = outputConfig?.output?.[outputId]\n      const visible = customConfig?.visible ?? !hasLink\n      this.outputVisibility.push(visible)\n      if (!visible) {\n        continue\n      }\n\n      const output = defOutput[outputId]\n      if (!isOutputTypeSpec(output)) continue\n\n      if (this.nodeDef?.output) {\n        oldToNew[outputId] = this.nodeDef.output.length\n        this.newToOldOutputMap[this.nodeDef.output.length] = {\n          node,\n          slot: outputId\n        }\n        this.nodeDef.output.push(output)\n        this.nodeDef.output_is_list?.push(\n          def.output_is_list?.[outputId] ?? false\n        )\n      }\n\n      let label: string | undefined = customConfig?.name\n      if (!label) {\n        const outputVal = defOutput[outputId]\n        label =\n          def.output_name?.[outputId] ??\n          (typeof outputVal === 'string' ? outputVal : undefined)\n        const output = node.outputs?.find((o) => o.name === label)\n        if (output?.label) {\n          label = output.label\n        }\n      }\n\n      let name = label ?? `output_${outputId}`\n      if (name in seenOutputs) {\n        const prefix = `${node.title ?? node.type} `\n        name = `${prefix}${label ?? outputId}`\n        if (name in seenOutputs) {\n          name = `${prefix}${node.index} ${label ?? outputId}`\n        }\n      }\n      seenOutputs[name] = 1\n\n      this.nodeDef?.output_name?.push(name)\n    }\n  }\n\n  static async registerFromWorkflow(\n    groupNodes: Record<string, GroupNodeWorkflowData>,\n    missingNodeTypes: (\n      | string\n      | {\n          type: string\n          nodeId?: string | number\n          hint?: string\n          action?: unknown\n        }\n    )[],\n    instanceIdsByGroup?: Map<string, (string | number)[]>\n  ) {\n    for (const g in groupNodes) {\n      const groupData = groupNodes[g]\n\n      const missingInnerTypes = [\n        ...new Set(\n          groupData.nodes\n            .filter(\n              (n) => !n.type || !(n.type in LiteGraph.registered_node_types)\n            )\n            .map((n) => n.type ?? 'unknown')\n        )\n      ]\n\n      if (missingInnerTypes.length) {\n        const groupType = `${PREFIX}${SEPARATOR}${g}`\n        const registeredGroupType = LiteGraph.registered_node_types[\n          groupType\n        ] as LGraphNodeConstructor | undefined\n        if (registeredGroupType?.nodeData?.[GROUP]) {\n          LiteGraph.unregisterNodeType(groupType)\n          useNodeDefStore().removeNodeDef(groupType)\n        }\n        const removeAction = {\n          text: 'Remove from workflow',\n          callback: (e?: MouseEvent) => {\n            delete groupNodes[g]\n            const target = e?.target as HTMLElement | undefined\n            if (!target) return\n            target.textContent = 'Removed'\n            target.style.pointerEvents = 'none'\n            target.style.opacity = '0.7'\n          }\n        }\n        if (instanceIdsByGroup) {\n          // One report per canvas instance so every entry is backed by a\n          // real node and can be retired when that node goes away. A group\n          // definition with no instances gets no report: there is no node\n          // to locate, and nothing that could ever retire the row.\n          for (const id of instanceIdsByGroup.get(g) ?? []) {\n            missingNodeTypes.push({\n              type: groupType,\n              nodeId: String(id),\n              hint: t('g.missingNodeTypesInGroup', {\n                types: missingInnerTypes.join(', ')\n              }),\n              action: removeAction\n            })\n          }\n        } else {\n          for (const missingType of missingInnerTypes) {\n            missingNodeTypes.push({\n              type: missingType,\n              hint: ` (In group node '${groupType}')`\n            })\n          }\n          missingNodeTypes.push({ type: groupType, action: removeAction })\n        }\n        continue\n      }\n\n      const config = new GroupNodeConfig(g, groupData)\n      await config.registerType()\n    }\n  }\n}\n\n/**\n * Finds the outer widget matching `name`, skipping any index already in\n * `consumed`.\n *\n * Widget names inside a synthesized group-node type are meant to be unique\n * (see {@link GroupNodeConfig.getInputConfig}'s de-duplication), so pairing\n * by name alone is normally safe. But it is not *guaranteed* unique across\n * every inner node/widget combination, and a plain `Array.findIndex` always\n * resolves a shared name to the *first* matching widget — silently copying\n * that node's value into every other inner node exposing a widget with the\n * same final name. Consuming each match exactly once, in the same\n * node-by-node order the inner nodes are unpacked, keeps every widget paired\n * with the widget belonging to its own originating node even when two\n * inner nodes end up sharing an outer widget name (e.g. two `CLIPTextEncode`\n * nodes both exposing `text`).\n */\nexport function findUnconsumedWidgetIndex(\n  widgets: { name?: string }[] | undefined,\n  name: string,\n  consumed: Set<number>\n): number {\n  if (!widgets) return -1\n  for (let i = 0; i < widgets.length; i++) {\n    if (consumed.has(i)) continue\n    if (widgets[i]?.name === name) return i\n  }\n  return -1\n}\n\n/**\n * Migration-only adapter for deprecated group nodes.\n *\n * Group nodes are no longer a supported feature. When a legacy workflow that\n * contains group nodes is loaded, {@link GroupNodeConfig.registerFromWorkflow}\n * synthesizes temporary node types so the instances can be created during\n * `configure`. The load-time migration unpacks each instance via\n * {@link convertToNodes} and {@link LGraph.convertToSubgraph} repackages the\n * result as a subgraph.\n *\n */\nexport class GroupNodeHandler {\n  node: LGraphNode\n  groupData: GroupNodeConfig\n\n  constructor(node: LGraphNode, groupData: GroupNodeConfig) {\n    this.node = node\n    this.groupData = groupData\n  }\n\n  /**\n   * Unpacks this group node into its constituent nodes within the root graph,\n   * copying current widget values and reconnecting external links, then removes\n   * the group node. Returns the newly created nodes.\n   *\n   * Lossiness is accepted: group nodes nested inside subgraphs are unpacked into\n   * the root graph rather than their original container.\n   */\n  convertToNodes(): LGraphNode[] {\n    const node = this.node\n    const { nodeData, oldToNewWidgetMap, oldToNewInputMap, newToOldOutputMap } =\n      this.groupData\n\n    const addInnerNodes = () => {\n      // Clone the node data so we don't mutate it for other instances\n      const c = { ...nodeData }\n      c.nodes = c.nodes.map((n) => ({ ...n, id: undefined }))\n      deserialiseAndCreate(JSON.stringify(c), app.canvas)\n\n      const [x, y] = node.pos\n      let top: number | undefined\n      let left: number | undefined\n      // deserialiseAndCreate selects the created nodes in creation order, which\n      // matches nodeData.nodes order.\n      const selectedIds = Object.keys(app.canvas.selected_nodes)\n      const newNodes: LGraphNode[] = []\n      // Shared across every inner node processed below, in nodeData.nodes\n      // order, so a widget already paired to one inner node's value can\n      // never be matched again for another (see findUnconsumedWidgetIndex).\n      const consumedOuterWidgetIndices = new Set<number>()\n      for (let i = 0; i < selectedIds.length; i++) {\n        const selectedId = parseNodeId(selectedIds[i])\n        const newNode = selectedId\n          ? app.rootGraph.getNodeById(selectedId)\n          : null\n        const innerNodeData = nodeData.nodes.at(i)\n        if (!newNode) continue\n        newNodes.push(newNode)\n\n        if (left == null || newNode.pos[0] < left) left = newNode.pos[0]\n        if (top == null || newNode.pos[1] < top) top = newNode.pos[1]\n\n        if (!newNode.widgets || !innerNodeData) continue\n\n        const map = oldToNewWidgetMap[i]\n        if (!map) continue\n        for (const oldName of Object.keys(map)) {\n          const newName = map[oldName]\n          if (!newName) continue\n\n          const widgetIndex = findUnconsumedWidgetIndex(\n            node.widgets,\n            newName,\n            consumedOuterWidgetIndices\n          )\n          if (widgetIndex === -1) continue\n\n          // An index is only marked consumed once its value is actually\n          // copied, so a bail below (a missing inner widget, or fewer outer\n          // widgets than this PrimitiveNode has) can't permanently burn an\n          // index another inner node legitimately needs.\n          if (innerNodeData.type === 'PrimitiveNode') {\n            for (let j = 0; j < newNode.widgets.length; j++) {\n              const srcWidget = node.widgets?.[widgetIndex + j]\n              if (!srcWidget) continue\n              consumedOuterWidgetIndices.add(widgetIndex + j)\n              newNode.widgets[j].value = srcWidget.value\n            }\n          } else {\n            const outerWidget = node.widgets?.[widgetIndex]\n            const newWidget = newNode.widgets.find((w) => w.name === oldName)\n            if (!newWidget || !outerWidget) continue\n\n            consumedOuterWidgetIndices.add(widgetIndex)\n            newWidget.value = outerWidget.value\n            const linkedWidgets = outerWidget.linkedWidgets ?? []\n            for (let w = 0; w < linkedWidgets.length; w++) {\n              const newLinked = newWidget.linkedWidgets?.[w]\n              if (newLinked && linkedWidgets[w]) {\n                newLinked.value = linkedWidgets[w].value\n              }\n            }\n          }\n        }\n      }\n\n      // Shift each node so the unpacked group appears at the group node position\n      for (const newNode of newNodes) {\n        newNode.pos = [\n          newNode.pos[0] - ((left ?? 0) - x),\n          newNode.pos[1] - ((top ?? 0) - y)\n        ]\n      }\n\n      return { newNodes, selectedIds }\n    }\n\n    const reconnectInputs = (selectedIds: (string | number)[]) => {\n      for (const [innerNodeIndex, map] of Object.entries(oldToNewInputMap)) {\n        const selectedId = parseNodeId(selectedIds[Number(innerNodeIndex)])\n        const newNode = selectedId\n          ? app.rootGraph.getNodeById(selectedId)\n          : null\n        if (!newNode || !map) continue\n        for (const [innerInputName, groupSlotId] of Object.entries(map)) {\n          const link = node.getInputLink(groupSlotId)\n          if (!link) continue\n          const originNode = app.rootGraph.getNodeById(link.origin_id)\n          const innerInputId = newNode.findInputSlot(innerInputName)\n          if (innerInputId !== -1) {\n            originNode?.connect(link.origin_slot, newNode, innerInputId)\n          }\n        }\n      }\n    }\n\n    const reconnectOutputs = (selectedIds: (string | number)[]) => {\n      for (\n        let groupOutputId = 0;\n        groupOutputId < node.outputs.length;\n        groupOutputId++\n      ) {\n        const links = outputLinks(app.rootGraph, node.id, groupOutputId)\n        for (const link of links) {\n          const slot = newToOldOutputMap[groupOutputId]\n          if (!slot) continue\n          const targetNode = app.rootGraph.getNodeById(link.target_id)\n          const selectedId = parseNodeId(selectedIds[slot.node.index ?? 0])\n          const newNode = selectedId\n            ? app.rootGraph.getNodeById(selectedId)\n            : null\n          if (targetNode) {\n            newNode?.connect(slot.slot, targetNode, link.target_slot)\n          }\n        }\n      }\n    }\n\n    app.canvas.emitBeforeChange()\n    try {\n      const { newNodes, selectedIds } = addInnerNodes()\n      reconnectInputs(selectedIds)\n      reconnectOutputs(selectedIds)\n      app.rootGraph.remove(this.node)\n      return newNodes\n    } finally {\n      app.canvas.emitAfterChange()\n    }\n  }\n\n  static getHandler(node: LGraphNode): GroupNodeHandler | undefined {\n    const cached = (node as LGraphNode & { [GROUP]?: GroupNodeHandler })[GROUP]\n    if (cached) return cached\n    const groupData = groupConfigOf(node)\n    if (!groupData) return undefined\n    const handler = new GroupNodeHandler(node, groupData)\n    ;(node as LGraphNode & { [GROUP]: GroupNodeHandler })[GROUP] = handler\n    return handler\n  }\n\n  static isGroupNode(node: LGraphNode) {\n    return groupConfigOf(node) !== undefined\n  }\n}\n\nfunction groupConfigOf(node: LGraphNode): GroupNodeConfig | undefined {\n  const config = node.constructor.nodeData?.[GROUP]\n  return config instanceof GroupNodeConfig ? config : undefined\n}\n\nexport const replaceLegacySeparators = (nodes: ComfyNode[]): void => {\n  for (const node of nodes) {\n    if (typeof node.type === 'string' && node.type.startsWith('workflow/')) {\n      node.type = node.type.replace(/^workflow\\//, `${PREFIX}${SEPARATOR}`)\n    }\n  }\n}\n\n/**\n * Converts every group node in the root graph to a subgraph. Re-scans until none\n * remain so group nodes revealed by a previous conversion are also migrated. A\n * failed conversion removes the offending node so loading can continue (accepted\n * lossiness) and the scan cannot loop forever.\n * @returns the number of group nodes converted\n */\nfunction convertLoadedGroupNodes(): number {\n  let converted = 0\n  const failed = new Set<LGraphNode>()\n  for (;;) {\n    const node = app.rootGraph.nodes.find(\n      (n) => GroupNodeHandler.isGroupNode(n) && !failed.has(n)\n    )\n    if (!node) return converted\n    try {\n      const handler = GroupNodeHandler.getHandler(node)\n      if (!handler) {\n        console.error('Missing handler for group node')\n        failed.add(node)\n        app.rootGraph.remove(node)\n        continue\n      }\n      const innerNodes = handler.convertToNodes()\n      for (const inner of innerNodes) inner.updateArea()\n      app.rootGraph.convertToSubgraph(new Set(innerNodes))\n      converted++\n    } catch (error) {\n      console.error('Failed to convert group node to subgraph', error)\n      failed.add(node)\n      try {\n        app.rootGraph.remove(node)\n      } catch (removeError) {\n        console.error(\n          'Failed to remove group node after conversion failure',\n          removeError\n        )\n      }\n    }\n  }\n}\n\nconst groupNodeReportIndices = new WeakMap<\n  Exclude<MissingNodeType, string>,\n  number\n>()\n\nconst id = 'Comfy.GroupNode'\n\n/**\n * Global node definitions cache. Populated by `addCustomNodeDefs` during\n * extension initialization and read by {@link GroupNodeConfig.getNodeDef} when\n * synthesizing temporary group-node definitions during load.\n */\nlet globalDefs: Partial<Record<string, ComfyNodeDef>> = {}\nconst ext: ComfyExtension = {\n  name: id,\n  addCustomNodeDefs(defs: Record<string, ComfyNodeDef>) {\n    globalDefs = defs\n  },\n  async beforeConfigureGraph(\n    graphData: ComfyWorkflowJSON,\n    missingNodeTypes: MissingNodeType[]\n  ) {\n    const nodes = graphData.extra?.groupNodes as\n      | Record<string, GroupNodeWorkflowData>\n      | undefined\n    if (nodes) {\n      replaceLegacySeparators(graphData.nodes)\n      const instanceIndicesByGroup = new Map<string, number[]>()\n      const groupTypePrefix = `${PREFIX}${SEPARATOR}`\n      for (const [nodeIndex, n] of graphData.nodes.entries()) {\n        if (!n.type.startsWith(groupTypePrefix)) continue\n        const groupName = n.type.slice(groupTypePrefix.length)\n        const indices = instanceIndicesByGroup.get(groupName) ?? []\n        indices.push(nodeIndex)\n        instanceIndicesByGroup.set(groupName, indices)\n      }\n      const groupNodeReports: MissingNodeType[] = []\n      await GroupNodeConfig.registerFromWorkflow(\n        nodes,\n        groupNodeReports,\n        instanceIndicesByGroup\n      )\n      for (const report of groupNodeReports) {\n        if (typeof report === 'string' || report.nodeId == null) continue\n        const nodeIndex = Number(report.nodeId)\n        if (Number.isInteger(nodeIndex)) {\n          groupNodeReportIndices.set(report, nodeIndex)\n        }\n      }\n      missingNodeTypes.push(...groupNodeReports)\n    }\n  },\n  afterConfigureGraph(missingNodeTypes) {\n    for (let index = missingNodeTypes.length - 1; index >= 0; index--) {\n      const report = missingNodeTypes[index]\n      if (typeof report === 'string') continue\n      const nodeIndex = groupNodeReportIndices.get(report)\n      if (nodeIndex === undefined) continue\n      groupNodeReportIndices.delete(report)\n      const node = app.rootGraph.nodes.at(nodeIndex)\n      if (node) {\n        report.nodeId = String(node.id)\n      } else {\n        missingNodeTypes.splice(index, 1)\n      }\n    }\n    if (convertLoadedGroupNodes() > 0) {\n      delete app.rootGraph.extra.groupNodes\n    }\n  },\n  nodeCreated(node: LGraphNode) {\n    if (!GroupNodeHandler.isGroupNode(node)) return\n    const handler = GroupNodeHandler.getHandler(node)\n    // A stray group node created after load (e.g. paste) has no migration pass;\n    // convert it to a subgraph once it has joined a graph.\n    if (!app.configuringGraph) {\n      queueMicrotask(() => {\n        const graph = node.graph\n        if (graph && handler && GroupNodeHandler.isGroupNode(node)) {\n          try {\n            const innerNodes = handler.convertToNodes()\n            for (const inner of innerNodes) inner.updateArea()\n            graph.convertToSubgraph(new Set(innerNodes))\n          } catch (error) {\n            console.error(\n              'Failed to convert stray group node to subgraph',\n              error\n            )\n          }\n        }\n      })\n    }\n  }\n}\n\napp.registerExtension(ext)\n","import type { Positionable } from '@/lib/litegraph/src/interfaces'\nimport type { IContextMenuValue } from '@/lib/litegraph/src/types/contextMenu'\nimport { LGraphEventMode, LGraphGroup } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode, LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { ComfyExtension } from '@/types/comfy'\n\nimport { app } from '../../scripts/app'\n\nfunction setNodeMode(node: LGraphNode, mode: LGraphEventMode) {\n  node.mode = mode\n  node.graph?.change()\n}\n\nconst MODE_MENU_ITEMS = [\n  { content: 'Set Group Nodes to Always', mode: LGraphEventMode.ALWAYS },\n  { content: 'Set Group Nodes to Never', mode: LGraphEventMode.NEVER },\n  { content: 'Bypass Group Nodes', mode: LGraphEventMode.BYPASS }\n] as const\n\nfunction addNodesToGroup(group: LGraphGroup, items: Iterable<Positionable>) {\n  const padding = useSettingStore().get('Comfy.GroupSelectedNodes.Padding')\n  group.resizeTo([...group.children, ...items], padding)\n}\n\nconst ext: ComfyExtension = {\n  name: 'Comfy.GroupOptions',\n\n  getCanvasMenuItems(canvas: LGraphCanvas): (IContextMenuValue | null)[] {\n    const items: (IContextMenuValue | null)[] = []\n    const graph = canvas.graph\n    if (!graph) return items\n\n    const group = graph.getGroupOnPos(\n      canvas.graph_mouse[0],\n      canvas.graph_mouse[1]\n    )\n\n    if (!group) {\n      if (canvas.selectedItems.size > 0) {\n        items.push({\n          content: 'Add Group For Selected Nodes',\n          callback: () => {\n            const group = new LGraphGroup()\n            addNodesToGroup(group, canvas.selectedItems)\n            graph.add(group)\n            graph.change()\n\n            group.recomputeInsideNodes()\n          }\n        })\n      }\n\n      return items\n    }\n\n    // Group nodes aren't recomputed until the group is moved, this ensures the nodes are up-to-date\n    group.recomputeInsideNodes()\n    const nodesInGroup = group.nodes\n\n    items.push({\n      content: 'Add Selected Nodes To Group',\n      disabled: !canvas.selectedItems.size,\n      callback: () => {\n        addNodesToGroup(group, canvas.selectedItems)\n        graph.change()\n      }\n    })\n\n    // No nodes in group, return default options\n    if (nodesInGroup.length === 0) {\n      return items\n    } else {\n      // Add a separator between the default options and the group options\n      items.push(null)\n    }\n\n    const firstMode = nodesInGroup[0].mode\n    const sharedMode = nodesInGroup.every((node) => node.mode === firstMode)\n      ? firstMode\n      : undefined\n\n    items.push({\n      content: 'Fit Group To Nodes',\n      callback: () => {\n        group.recomputeInsideNodes()\n        const padding = useSettingStore().get(\n          'Comfy.GroupSelectedNodes.Padding'\n        )\n        group.resizeTo(group.children, padding)\n        graph.change()\n      }\n    })\n\n    items.push({\n      content: 'Select Nodes',\n      callback: () => {\n        canvas.selectNodes(nodesInGroup)\n        graph.change()\n        canvas.canvas.focus()\n      }\n    })\n\n    for (const { content, mode } of MODE_MENU_ITEMS) {\n      if (mode === sharedMode) continue\n\n      items.push({\n        content,\n        callback: () => {\n          for (const node of nodesInGroup) {\n            setNodeMode(node, mode)\n          }\n        }\n      })\n    }\n\n    return items\n  }\n}\n\napp.registerExtension(ext)\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useExtensionService } from '@/services/extensionService'\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.ImageCompare',\n\n  async nodeCreated(node: LGraphNode) {\n    if (node.constructor.comfyClass !== 'ImageCompare') return\n\n    const [oldWidth, oldHeight] = node.size\n    node.setSize([Math.max(oldWidth, 400), Math.max(oldHeight, 350)])\n  }\n})\n","import type { CompositorBBox } from '@/renderer/extensions/compositor/composables/compositorLayerState'\nimport type { ImageFileRef } from '@/renderer/extensions/compositor/composables/compositorPaths'\nimport { resetCompositorStateWidgets } from '@/renderer/extensions/compositor/composables/compositorWidgets'\nimport {\n  clearCompositorLayers,\n  clearCompositorPreviewOverride,\n  setCompositorLayers\n} from '@/renderer/extensions/compositor/composables/useCompositorLayers'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { NodeOutputWith } from '@/platform/remote/comfyui/execution/types'\nimport { useExtensionService } from '@/services/extensionService'\n\ntype ImageCompositorOutput = NodeOutputWith<{\n  compositor_layers?: Partial<ImageFileRef>[]\n  compositor_inputs?: string[]\n  compositor_bboxes?: (CompositorBBox | null)[]\n  compositor_canvas?: { w: number; h: number }[]\n  compositor_state_stale?: boolean[]\n}>\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.ImageCompositor',\n\n  nodeCreated(node: LGraphNode) {\n    if (node.constructor.comfyClass !== 'ImageCompositor') return\n\n    const [oldWidth, oldHeight] = node.size\n    node.setSize([Math.max(oldWidth, 300), Math.max(oldHeight, 400)])\n\n    node.hideOutputImages = true\n\n    const onExecuted = node.onExecuted\n    node.onExecuted = function (output: ImageCompositorOutput) {\n      onExecuted?.call(this, output)\n\n      const kept = (output.compositor_layers ?? []).flatMap(\n        ({ filename, subfolder = '', type = 'temp' }, index) =>\n          filename ? [{ layer: { filename, subfolder, type }, index }] : []\n      )\n      const layers = kept.map(({ layer }) => layer)\n      const rawBboxes = output.compositor_bboxes\n      const bboxes = rawBboxes\n        ? kept.map(({ index }) => rawBboxes[index] ?? null)\n        : undefined\n      if (layers.length)\n        setCompositorLayers(\n          node,\n          layers,\n          output.compositor_inputs,\n          bboxes,\n          output.compositor_canvas?.[0]\n        )\n      clearCompositorPreviewOverride(node)\n\n      if (output.compositor_state_stale?.[0]) {\n        resetCompositorStateWidgets(node)\n        node.graph?.setDirtyCanvas(true)\n      }\n    }\n\n    const onRemoved = node.onRemoved\n    node.onRemoved = function () {\n      onRemoved?.call(this)\n      clearCompositorLayers(node)\n    }\n  }\n})\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useExtensionService } from '@/services/extensionService'\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.ImageCrop',\n\n  async nodeCreated(node: LGraphNode) {\n    if (node.constructor.comfyClass !== 'ImageCropV2') return\n\n    node.hideOutputImages = true\n    const [oldWidth, oldHeight] = node.size\n    node.setSize([Math.max(oldWidth, 300), Math.max(oldHeight, 450)])\n  }\n})\n","import { app } from '@/scripts/app'\n\napp.registerExtension({\n  name: 'Comfy.LayerEditor',\n  commands: [\n    {\n      id: 'Comfy.LayerEditor.OpenLayerEditor',\n      icon: 'pi pi-images',\n      label: 'Open Layer Editor for Selected Node',\n      function: async () => {\n        const selectedNodes = app.canvas.selected_nodes\n        if (Object.keys(selectedNodes).length !== 1) return\n\n        const selectedNode = selectedNodes[Object.keys(selectedNodes)[0]]\n        const { useLayerEditor } =\n          await import('@/renderer/extensions/layerEditor/composables/useLayerEditor')\n        useLayerEditor().openLayerEditor(selectedNode)\n      }\n    }\n  ]\n})\n","/**\n * Lazy loader for 3D extensions (Load3D, Preview3D, SaveGLB)\n *\n * This module defers loading of THREE.js (~1.8MB) until a 3D node is actually\n * used in a workflow. The heavy imports are only loaded when:\n * - A workflow containing 3D nodes is loaded\n * - A user adds a 3D node from the node menu\n */\n\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { ComfyNodeDef } from '@/schemas/nodeDefSchema'\nimport { app } from '@/scripts/app'\nimport { useExtensionService } from '@/services/extensionService'\nimport { useExtensionStore } from '@/stores/extensionStore'\n\nimport type { ComfyExtension } from '@/types/comfy'\n\nimport { isLoad3dNode, isThreeJsNode } from './load3d/nodeTypes'\n\nlet load3dExtensionsLoaded = false\nlet load3dExtensionsLoading: Promise<ComfyExtension[]> | null = null\n\n/**\n * Dynamically load the 3D extensions (and THREE.js) on demand.\n * Returns the list of newly registered extensions so the caller can\n * replay hooks that they missed.\n */\nasync function loadLoad3dExtensions(): Promise<ComfyExtension[]> {\n  if (load3dExtensionsLoaded) return []\n\n  if (load3dExtensionsLoading) {\n    return load3dExtensionsLoading\n  }\n\n  load3dExtensionsLoading = (async () => {\n    const before = new Set(useExtensionStore().enabledExtensions)\n    // Import extensions - they self-register via useExtensionService()\n    await Promise.all([\n      import('./load3d'),\n      import('./load3dAdvanced'),\n      import('./load3dPreviewExtensions'),\n      import('./saveMesh'),\n      import('./cameraInfo'),\n      import('./cameraAngle'),\n      import('./lightInfo')\n    ])\n    load3dExtensionsLoaded = true\n    return useExtensionStore().enabledExtensions.filter(\n      (ext) => !before.has(ext)\n    )\n  })()\n\n  return load3dExtensionsLoading\n}\n\n// Register a lightweight extension that triggers lazy loading\nuseExtensionService().registerExtension({\n  name: 'Comfy.Load3DLazy',\n\n  async beforeRegisterNodeDef(\n    nodeType: typeof LGraphNode,\n    nodeData: ComfyNodeDef\n  ) {\n    if (!isThreeJsNode(nodeData.name)) return\n\n    if (isLoad3dNode(nodeData.name)) {\n      // Inject mesh_upload spec flags so WidgetSelect.vue can detect\n      // Load3D's model_file as a mesh upload widget without hardcoding.\n      if (nodeData.name === 'Load3D' || nodeData.name === 'Load3DAdvanced') {\n        const modelFile = nodeData.input?.required?.model_file\n        if (modelFile?.[1]) {\n          modelFile[1].mesh_upload = true\n          modelFile[1].upload_subfolder = '3d'\n        }\n      }\n    }\n\n    // Load the 3D extensions and replay their beforeRegisterNodeDef hooks,\n    // since invokeExtensionsAsync already captured the extensions snapshot\n    // before these new extensions were registered.\n    const newExtensions = await loadLoad3dExtensions()\n    for (const ext of newExtensions) {\n      await ext.beforeRegisterNodeDef?.(nodeType, nodeData, app)\n    }\n  }\n})\n","import _ from 'es-toolkit/compat'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\nimport { app, ComfyApp } from '@/scripts/app'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useMaskEditor } from '@/composables/maskeditor/useMaskEditor'\nimport { useCanvasTransform } from '@/composables/maskeditor/useCanvasTransform'\nimport { markCoreMediaMenuCallback } from '@/utils/coreMediaMenuActionUtils'\nimport { isImageNode } from '@/utils/litegraphUtil'\n\nfunction openMaskEditor(node: LGraphNode): void {\n  if (!node.imgs?.length && node.previewMediaType !== 'image') {\n    console.error('[MaskEditor] Node has no images')\n    return\n  }\n\n  useMaskEditor().openMaskEditor(node)\n}\n\n// Open mask editor from clipspace (for plugin compatibility)\n// This is called when ComfyApp.open_maskeditor() is invoked without arguments\nfunction openMaskEditorFromClipspace(): void {\n  const node = ComfyApp.clipspace_return_node\n  if (!node) {\n    console.error('[MaskEditor] No clipspace_return_node found')\n    return\n  }\n\n  openMaskEditor(node)\n}\n\n// Check if the dialog is already opened\nfunction isOpened(): boolean {\n  return useDialogStore().isDialogOpen('global-mask-editor')\n}\n\nconst changeBrushSize = async (sizeChanger: (oldSize: number) => number) => {\n  if (!isOpened()) return\n\n  const store = useMaskEditorStore()\n  const oldBrushSize = store.brushSettings.size\n  const newBrushSize = sizeChanger(oldBrushSize)\n  store.setBrushSize(newBrushSize)\n}\n\napp.registerExtension({\n  name: 'Comfy.MaskEditor',\n  settings: [\n    {\n      id: 'Comfy.MaskEditor.BrushAdjustmentSpeed',\n      category: ['Mask Editor', 'BrushAdjustment', 'Sensitivity'],\n      name: 'Brush adjustment speed multiplier',\n      tooltip:\n        'Controls how quickly the brush size and hardness change when adjusting. Higher values mean faster changes.',\n      type: 'slider',\n      attrs: {\n        min: 0.1,\n        max: 2.0,\n        step: 0.1\n      },\n      defaultValue: 1.0,\n      versionAdded: '1.0.0'\n    },\n    {\n      id: 'Comfy.MaskEditor.UseDominantAxis',\n      category: ['Mask Editor', 'BrushAdjustment', 'UseDominantAxis'],\n      name: 'Lock brush adjustment to dominant axis',\n      tooltip:\n        'When enabled, brush adjustments will only affect size OR hardness based on which direction you move more',\n      type: 'boolean',\n      defaultValue: true\n    }\n  ],\n  commands: [\n    {\n      id: 'Comfy.MaskEditor.OpenMaskEditor',\n      icon: 'pi pi-pencil',\n      label: 'Open Mask Editor for Selected Node',\n      function: () => {\n        const selectedNodes = app.canvas.selected_nodes\n        if (Object.keys(selectedNodes).length !== 1) return\n\n        const selectedNode = selectedNodes[Object.keys(selectedNodes)[0]]\n        openMaskEditor(selectedNode)\n      }\n    },\n    {\n      id: 'Comfy.MaskEditor.BrushSize.Increase',\n      icon: 'pi pi-plus-circle',\n      label: 'Increase Brush Size in MaskEditor',\n      function: () => changeBrushSize((old) => _.clamp(old + 2, 1, 250))\n    },\n    {\n      id: 'Comfy.MaskEditor.BrushSize.Decrease',\n      icon: 'pi pi-minus-circle',\n      label: 'Decrease Brush Size in MaskEditor',\n      function: () => changeBrushSize((old) => _.clamp(old - 2, 1, 250))\n    },\n    {\n      id: 'Comfy.MaskEditor.ColorPicker',\n      icon: 'pi pi-palette',\n      label: 'Open Color Picker in MaskEditor',\n      function: () => {\n        if (!isOpened()) return\n\n        const store = useMaskEditorStore()\n        store.colorInput?.click()\n      }\n    },\n    {\n      id: 'Comfy.MaskEditor.Rotate.Right',\n      icon: 'pi pi-refresh',\n      label: 'Rotate Right in MaskEditor',\n      function: async () => {\n        if (!isOpened()) return\n        await useCanvasTransform().rotateClockwise()\n      }\n    },\n    {\n      id: 'Comfy.MaskEditor.Rotate.Left',\n      icon: 'pi pi-undo',\n      label: 'Rotate Left in MaskEditor',\n      function: async () => {\n        if (!isOpened()) return\n        await useCanvasTransform().rotateCounterclockwise()\n      }\n    },\n    {\n      id: 'Comfy.MaskEditor.Mirror.Horizontal',\n      icon: 'pi pi-arrows-h',\n      label: 'Mirror Horizontal in MaskEditor',\n      function: async () => {\n        if (!isOpened()) return\n        await useCanvasTransform().mirrorHorizontal()\n      }\n    },\n    {\n      id: 'Comfy.MaskEditor.Mirror.Vertical',\n      icon: 'pi pi-arrows-v',\n      label: 'Mirror Vertical in MaskEditor',\n      function: async () => {\n        if (!isOpened()) return\n        await useCanvasTransform().mirrorVertical()\n      }\n    }\n  ],\n  beforeRegisterNodeDef(nodeType: typeof LGraphNode) {\n    const original = nodeType.prototype.getExtraMenuOptions\n    nodeType.prototype.getExtraMenuOptions = function (canvas, options) {\n      const extra = original?.call(this, canvas, options) ?? []\n      if (ComfyApp.clipspace_return_node || !isImageNode(this)) return extra\n\n      options.push({\n        content: 'Open in MaskEditor | Image Canvas',\n        callback: markCoreMediaMenuCallback(() => {\n          useMaskEditor().openMaskEditor(this)\n        }, 'preview')\n      })\n      return extra\n    }\n  },\n  init() {\n    // Set up ComfyApp static methods for plugin compatibility (deprecated)\n    ComfyApp.open_maskeditor = openMaskEditorFromClipspace\n\n    console.warn(\n      '[MaskEditor] ComfyApp.open_maskeditor is deprecated. ' +\n        'Plugins should migrate to using the command system or direct node context menu integration.'\n    )\n  }\n})\n","import {\n  LGraphCanvas,\n  LiteGraph,\n  LGraphNode\n} from '@/lib/litegraph/src/litegraph'\n\nimport { app } from '../../scripts/app'\nimport { ComfyWidgets } from '../../scripts/widgets'\n\n// Node that add notes to your project\n\napp.registerExtension({\n  name: 'Comfy.NoteNode',\n  registerCustomNodes() {\n    class NoteNode extends LGraphNode {\n      static override category: string\n      static collapsable: boolean\n      static title_mode: number\n\n      groupcolor = LGraphCanvas.node_colors.yellow.groupcolor\n      override isVirtualNode: boolean\n\n      constructor(title: string) {\n        super(title)\n\n        this.color = LGraphCanvas.node_colors.yellow.color\n        this.bgcolor = LGraphCanvas.node_colors.yellow.bgcolor\n\n        ComfyWidgets.STRING(\n          this,\n          'text',\n          ['STRING', { default: this.properties.text, multiline: true }],\n          app\n        )\n\n        this.serialize_widgets = true\n        this.isVirtualNode = true\n      }\n    }\n\n    // Load default visibility\n\n    LiteGraph.registerNodeType(\n      'Note',\n      Object.assign(NoteNode, {\n        title_mode: LiteGraph.NORMAL_TITLE,\n        title: 'Note',\n        collapsable: true\n      })\n    )\n\n    NoteNode.category = 'utilities'\n\n    /** Markdown variant of NoteNode */\n    class MarkdownNoteNode extends LGraphNode {\n      static override title = 'Markdown Note'\n\n      groupcolor = LGraphCanvas.node_colors.yellow.groupcolor\n\n      constructor(title: string) {\n        super(title)\n\n        this.color = LGraphCanvas.node_colors.yellow.color\n        this.bgcolor = LGraphCanvas.node_colors.yellow.bgcolor\n\n        ComfyWidgets.MARKDOWN(\n          this,\n          'text',\n          ['STRING', { default: this.properties.text }],\n          app\n        )\n\n        this.serialize_widgets = true\n        this.isVirtualNode = true\n      }\n    }\n\n    LiteGraph.registerNodeType('MarkdownNote', MarkdownNoteNode)\n    MarkdownNoteNode.category = 'utilities'\n  }\n})\n","import { useExtensionService } from '@/services/extensionService'\n\nconst HIDDEN_WIDGETS = new Set(['width', 'height', 'bg_color'])\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.Painter',\n\n  nodeCreated(node) {\n    if (node.constructor.comfyClass !== 'Painter') return\n\n    const [oldWidth, oldHeight] = node.size\n    node.setSize([Math.max(oldWidth, 450), Math.max(oldHeight, 550)])\n\n    node.hideOutputImages = true\n\n    for (const widget of node.widgets ?? []) {\n      if (HIDDEN_WIDGETS.has(widget.name)) {\n        widget.hidden = true\n      }\n    }\n  }\n})\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { resolveNodeRootGraphId } from '@/lib/litegraph/src/litegraph'\nimport WidgetTextPreview from '@/renderer/extensions/vueNodes/widgets/components/WidgetTextPreview.vue'\nimport type { NodeExecutionOutput } from '@/platform/remote/comfyui/execution/types'\nimport type { CustomInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { app } from '@/scripts/app'\nimport { ComponentWidgetImpl, addWidget } from '@/scripts/domWidget'\nimport { ComfyWidgets } from '@/scripts/widgets'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { widgetId } from '@/types/widgetId'\n\nconst PREVIEW_WIDGET_NAME = 'preview_text'\nconst MODE_WIDGET_NAME = 'preview_mode'\n\nconst inputSpecTextPreview: CustomInputSpec = {\n  name: PREVIEW_WIDGET_NAME,\n  type: 'TEXT_PREVIEW',\n  isPreview: true\n}\n\nexport function addTextPreviewWidgets(node: LGraphNode) {\n  const widgetStore = useWidgetValueStore()\n  let fallbackValue = ''\n\n  const previewWidgetId = () =>\n    widgetId(\n      resolveNodeRootGraphId(node, app.rootGraph.id),\n      node.id,\n      PREVIEW_WIDGET_NAME\n    )\n\n  const preview = new ComponentWidgetImpl<string | object>({\n    node,\n    name: PREVIEW_WIDGET_NAME,\n    component: WidgetTextPreview,\n    inputSpec: inputSpecTextPreview,\n    type: 'textPreview',\n    options: {\n      serialize: false,\n      hideInPanel: true,\n      getMinHeight: () => 60,\n      getValue: () => {\n        const stored = widgetStore.getWidget(previewWidgetId())?.value\n        return typeof stored === 'string' ? stored : fallbackValue\n      },\n      setValue: (value: string | object) => {\n        fallbackValue = typeof value === 'string' ? value : ''\n        const state = widgetStore.getWidget(previewWidgetId())\n        if (state) state.value = fallbackValue\n      }\n    }\n  })\n  preview.serialize = false\n  addWidget(node, preview)\n\n  const modeWidget = ComfyWidgets['BOOLEAN'](\n    node,\n    MODE_WIDGET_NAME,\n    [\n      'BOOLEAN',\n      { label_on: 'Markdown', label_off: 'Plain text', default: false }\n    ],\n    app\n  ).widget\n\n  modeWidget.options.serialize = false\n  modeWidget.serialize = false\n}\n\nfunction toPreviewText(text: unknown): string {\n  if (text == null) return ''\n  if (Array.isArray(text))\n    return text.filter((part) => part != null).join('\\n\\n')\n  return String(text)\n}\n\nexport function updateTextPreviewWidgets(\n  node: LGraphNode,\n  message: NodeExecutionOutput | null | undefined\n) {\n  const preview = node.widgets?.find((w) => w.name === PREVIEW_WIDGET_NAME)\n  if (!preview) return\n\n  preview.value = toPreviewText(message?.text)\n}\n","/*\nPreview Any - original implement from\nhttps://github.com/rgthree/rgthree-comfy/blob/main/py/display_any.py\nupstream requested in https://github.com/Kosinkadink/rfcs/blob/main/rfcs/0000-corenodes.md#preview-nodes\n */\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport {\n  addTextPreviewWidgets,\n  updateTextPreviewWidgets\n} from '@/extensions/core/textPreviewWidgets'\nimport type { ComfyNodeDef } from '@/schemas/nodeDefSchema'\nimport { app } from '@/scripts/app'\nimport { useExtensionService } from '@/services/extensionService'\nimport { getNodeByLocatorId } from '@/utils/graphTraversalUtil'\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.PreviewAny',\n  async beforeRegisterNodeDef(\n    nodeType: typeof LGraphNode,\n    nodeData: ComfyNodeDef\n  ) {\n    if (nodeData.name !== 'PreviewAny') return\n\n    const onNodeCreated = nodeType.prototype.onNodeCreated\n    nodeType.prototype.onNodeCreated = function () {\n      onNodeCreated?.apply(this, [])\n      addTextPreviewWidgets(this)\n    }\n\n    const onExecuted = nodeType.prototype.onExecuted\n    nodeType.prototype.onExecuted = function (message) {\n      onExecuted?.apply(this, [message])\n      updateTextPreviewWidgets(this, message)\n    }\n  },\n  onNodeOutputsUpdated(nodeOutputs) {\n    for (const [nodeLocatorId, output] of Object.entries(nodeOutputs)) {\n      const node = getNodeByLocatorId(app.rootGraph, nodeLocatorId)\n      if (node?.type === 'PreviewAny') updateTextPreviewWidgets(node, output)\n    }\n  }\n})\n","import {\n  addTextPreviewWidgets,\n  updateTextPreviewWidgets\n} from '@/extensions/core/textPreviewWidgets'\nimport { useExtensionService } from '@/services/extensionService'\n\nuseExtensionService().registerExtension({\n  name: 'Comfy.saveText',\n  async beforeRegisterNodeDef(nodeType, nodeData) {\n    if (nodeData.name !== 'SaveText') return\n\n    const onNodeCreated = nodeType.prototype.onNodeCreated\n    nodeType.prototype.onNodeCreated = function () {\n      onNodeCreated?.apply(this, [])\n      addTextPreviewWidgets(this)\n    }\n\n    const onExecuted = nodeType.prototype.onExecuted\n    nodeType.prototype.onExecuted = function (message) {\n      onExecuted?.apply(this, [message])\n      updateTextPreviewWidgets(this, message)\n    }\n  }\n})\n","import type { IContextMenuValue, LGraph } from '@/lib/litegraph/src/litegraph'\nimport {\n  LGraphCanvas,\n  LGraphNode,\n  LiteGraph\n} from '@/lib/litegraph/src/litegraph'\nimport type { ISlotType } from '@/lib/litegraph/src/interfaces'\nimport { outputLinks } from '@/lib/litegraph/src/node/slotLinks'\nimport { slotTypeKey } from '@/lib/litegraph/src/utils/type'\n\nimport { app } from '../../scripts/app'\nimport { getWidgetConfig, mergeIfValid, setWidgetConfig } from './widgetInputs'\n\n// Node that allows you to redirect connections for cleaner graphs\n\napp.registerExtension({\n  name: 'Comfy.RerouteNode',\n  registerCustomNodes() {\n    interface RerouteNode extends LGraphNode {\n      __outputType?: string | number\n    }\n\n    class RerouteNode extends LGraphNode {\n      static override category: string | undefined\n      static defaultVisibility = false\n\n      constructor(title?: string) {\n        super(title ?? '')\n        this.properties.showOutputText = RerouteNode.defaultVisibility\n        this.properties.horizontal = false\n\n        this.addInput('', '*')\n        this.addOutput(this.properties.showOutputText ? '*' : '', '*')\n\n        this.setSize(this.computeSize())\n\n        // This node is purely frontend and does not impact the resulting prompt so should not be serialized\n        this.isVirtualNode = true\n      }\n      override onAfterGraphConfigured() {\n        requestAnimationFrame(() => {\n          this.onConnectionsChange(LiteGraph.INPUT, undefined, true)\n        })\n      }\n      override clone(): LGraphNode | null {\n        const cloned = super.clone()\n        if (!cloned) return cloned\n        cloned.removeOutput(0)\n        cloned.addOutput(this.properties.showOutputText ? '*' : '', '*')\n        cloned.setSize(cloned.computeSize())\n        return cloned\n      }\n      override onConnectionsChange(\n        type: ISlotType,\n        _index: number | undefined,\n        connected: boolean\n      ) {\n        const { graph } = this\n        if (!graph) return\n        if (app.configuringGraph) return\n\n        // Prevent multiple connections to different types when we have no input\n        if (connected && type === LiteGraph.OUTPUT) {\n          const links = outputLinks(graph, this.id, 0)\n          // Ignore wildcard nodes as these will be updated to real types\n          const types = new Set(\n            links.map((l) => l.type).filter((t) => t && t !== '*')\n          )\n          if (types.size > 1) {\n            const linksToDisconnect = links.slice(0, -1)\n            for (const link of linksToDisconnect) {\n              const node = graph.getNodeById(link.target_id)\n              node?.disconnectInput(link.target_slot)\n            }\n          }\n        }\n\n        const rootInput = findRootInput(this, graph)\n        if (!rootInput) return\n        const { updateNodes, inputNode, inputType } = rootInput\n\n        // Find all outputs\n        const nodes: RerouteNode[] = [this]\n        let outputType = null\n        while (nodes.length) {\n          const currentNode = nodes.pop()!\n          for (const link of outputLinks(graph, currentNode.id, 0)) {\n            const node = graph.getNodeById(link.target_id)\n            if (!node) continue\n            if (node instanceof RerouteNode) {\n              // Follow reroute nodes\n              nodes.push(node)\n              updateNodes.push(node)\n            } else {\n              // We've found an output\n              const nodeInput = node.inputs[link.target_slot]\n              const nodeOutType = nodeInput.type\n              const keep =\n                !inputType ||\n                !nodeOutType ||\n                LiteGraph.isValidConnection(inputType, nodeOutType)\n              if (!keep) {\n                // The output doesnt match our input so disconnect it\n                node.disconnectInput(link.target_slot)\n                continue\n              }\n              node.onConnectionsChange?.(\n                LiteGraph.INPUT,\n                link.target_slot,\n                keep,\n                link,\n                nodeInput\n              )\n              outputType = node.inputs[link.target_slot].type\n            }\n          }\n        }\n\n        const displayType = slotTypeKey(inputType || outputType || '*')\n        const color = LGraphCanvas.link_type_colors[displayType]\n\n        let widgetConfig\n        let widgetType\n        // Update the types of each node\n        for (const node of updateNodes) {\n          // If we dont have an input type we are always wildcard but we'll show the output type\n          // This lets you change the output link to a different type and all nodes will update\n          node.outputs[0].type = inputType || '*'\n          node.__outputType = displayType\n          node.outputs[0].name = node.properties.showOutputText\n            ? `${displayType}`\n            : ''\n          node.setSize(node.computeSize())\n\n          for (const link of outputLinks(graph, node.id, 0)) {\n            link.color = color\n\n            const targetNode = graph.getNodeById(link.target_id)\n            if (!targetNode) continue\n            const targetInput = targetNode.inputs.at(link.target_slot)\n            if (targetInput?.widget) {\n              const config = getWidgetConfig(targetInput)\n              if (!widgetConfig) {\n                widgetConfig = config[1] ?? {}\n                widgetType = config[0]\n              }\n\n              const merged = mergeIfValid(targetInput, [\n                config[0],\n                widgetConfig\n              ])\n              if (merged.customConfig) {\n                widgetConfig = merged.customConfig\n              }\n            }\n          }\n        }\n\n        for (const node of updateNodes) {\n          if (widgetConfig && outputType) {\n            node.inputs[0].widget = { name: 'value' }\n            setWidgetConfig(node.inputs[0], [\n              widgetType ?? `${displayType}`,\n              widgetConfig\n            ])\n          } else {\n            setWidgetConfig(node.inputs[0], undefined)\n          }\n        }\n\n        const inputNodeLink = inputNode?.getInputLink(0)\n        if (inputNodeLink) {\n          inputNodeLink.color = color\n        }\n      }\n\n      override getExtraMenuOptions(\n        _: unknown,\n        options: (IContextMenuValue | null)[]\n      ): IContextMenuValue[] {\n        options.unshift(\n          {\n            content:\n              (this.properties.showOutputText ? 'Hide' : 'Show') + ' Type',\n            callback: () => {\n              this.properties.showOutputText = !this.properties.showOutputText\n              if (this.properties.showOutputText) {\n                this.outputs[0].name = `${this.__outputType || this.outputs[0].type}`\n              } else {\n                this.outputs[0].name = ''\n              }\n              this.setSize(this.computeSize())\n              app.canvas.setDirty(true, true)\n            }\n          },\n          {\n            content:\n              (RerouteNode.defaultVisibility ? 'Hide' : 'Show') +\n              ' Type By Default',\n            callback: () => {\n              RerouteNode.setDefaultTextVisibility(\n                !RerouteNode.defaultVisibility\n              )\n            }\n          }\n        )\n        return []\n      }\n      override computeSize(): [number, number] {\n        return [\n          this.properties.showOutputText && this.outputs.length\n            ? Math.max(\n                75,\n                LiteGraph.NODE_TEXT_SIZE * this.outputs[0].name.length * 0.6 +\n                  40\n              )\n            : 75,\n          26\n        ]\n      }\n\n      static setDefaultTextVisibility(visible: boolean) {\n        RerouteNode.defaultVisibility = visible\n        if (visible) {\n          localStorage['Comfy.RerouteNode.DefaultVisibility'] = 'true'\n        } else {\n          delete localStorage['Comfy.RerouteNode.DefaultVisibility']\n        }\n      }\n    }\n\n    // Load default visibility\n    RerouteNode.setDefaultTextVisibility(\n      !!localStorage['Comfy.RerouteNode.DefaultVisibility']\n    )\n\n    function findRootInput(start: RerouteNode, graph: LGraph) {\n      const updateNodes: RerouteNode[] = [start]\n      let currentNode = start\n      let inputType: ISlotType | null = null\n      let inputNode: RerouteNode | null = null\n      while (currentNode.isInputConnected(0)) {\n        const link = currentNode.getInputLink(0)\n        if (!link) return null\n        const node = graph.getNodeById(link.origin_id)\n        if (!node) return null\n        if (!(node instanceof RerouteNode)) {\n          // We've found the end\n          inputNode = currentNode\n          inputType = node.outputs[link.origin_slot]?.type ?? null\n          break\n        }\n        if (node === start) {\n          // We've found a circle\n          currentNode.disconnectInput(link.target_slot)\n          break\n        }\n        // Move the previous node\n        updateNodes.unshift(node)\n        currentNode = node\n      }\n      return { updateNodes, inputNode, inputType }\n    }\n\n    LiteGraph.registerNodeType(\n      'Reroute',\n      Object.assign(RerouteNode, {\n        title_mode: LiteGraph.NO_TITLE,\n        title: 'Reroute',\n        collapsable: false\n      })\n    )\n\n    RerouteNode.category = 'utilities'\n  }\n})\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { ComfyNodeDef } from '@/schemas/nodeDefSchema'\nimport { applyTextReplacements } from '@/utils/searchAndReplace'\n\nimport { app } from '../../scripts/app'\n\nconst saveNodeTypes = new Set([\n  'SaveImage',\n  'SaveImageAdvanced',\n  'SaveSVGNode',\n  'SaveVideo',\n  'SaveAnimatedWEBP',\n  'SaveWEBM',\n  'SaveAudio',\n  'SaveAudioMP3',\n  'SaveAudioOpus',\n  'SaveAudioAdvanced',\n  'SaveGLB',\n  'Save3DAdvanced',\n  'SaveGaussianSplat',\n  'SavePointCloud',\n  'SaveAnimatedPNG',\n  'CLIPSave',\n  'VAESave',\n  'ModelSave',\n  'LoraSave',\n  'SaveLatent'\n])\n\n// Use widget values and dates in output filenames\n\napp.registerExtension({\n  name: 'Comfy.SaveImageExtraOutput',\n  async beforeRegisterNodeDef(\n    nodeType: typeof LGraphNode,\n    nodeData: ComfyNodeDef\n  ) {\n    if (saveNodeTypes.has(nodeData.name)) {\n      const onNodeCreated = nodeType.prototype.onNodeCreated\n      // When the SaveImage node is created we want to override the serialization of the output name widget to run our S&R\n      nodeType.prototype.onNodeCreated = function () {\n        const r = onNodeCreated?.call(this)\n\n        const widget = this.widgets?.find((w) => w.name === 'filename_prefix')\n        if (!widget) return r\n        widget.serializeValue = () =>\n          typeof widget.value === 'string'\n            ? applyTextReplacements(app.graph, widget.value)\n            : widget.value\n\n        return r\n      }\n    } else {\n      // When any other node is created add a property to alias the node\n      const onNodeCreated = nodeType.prototype.onNodeCreated\n      nodeType.prototype.onNodeCreated = function () {\n        const r = onNodeCreated?.call(this)\n\n        if (!('Node name for S&R' in this.properties)) {\n          this.addProperty('Node name for S&R', this.constructor.type, 'string')\n        }\n\n        return r\n      }\n    }\n  }\n})\n","import { SELECTION_BOUNDS_PADDING } from '@/base/common/selectionBounds'\nimport type { LGraphCanvas, Rectangle } from '@/lib/litegraph/src/litegraph'\nimport { createBounds } from '@/lib/litegraph/src/litegraph'\nimport { app } from '@/scripts/app'\n\n/**\n * Draws a dashed border around selected items that maintains constant pixel size\n * regardless of zoom level, similar to the DOM selection overlay.\n */\nfunction drawSelectionBorder(\n  ctx: CanvasRenderingContext2D,\n  canvas: LGraphCanvas\n) {\n  const selectedItems = canvas.selectedItems\n\n  // Only draw if multiple items selected\n  if (selectedItems.size <= 1) return\n\n  // Use the same bounds calculation as the toolbox\n  const bounds = createBounds(selectedItems, SELECTION_BOUNDS_PADDING)\n  if (!bounds) return\n\n  const [x, y, width, height] = bounds\n\n  // Save context state\n  ctx.save()\n\n  // Set up dashed line style that doesn't scale with zoom\n  const borderWidth = 2 / canvas.ds.scale // Constant 2px regardless of zoom\n  ctx.lineWidth = borderWidth\n  ctx.strokeStyle =\n    getComputedStyle(document.documentElement)\n      .getPropertyValue('--border-color')\n      .trim() || '#ffffff66'\n\n  // Create dash pattern that maintains visual size\n  const dashSize = 5 / canvas.ds.scale\n  ctx.setLineDash([dashSize, dashSize])\n\n  // Draw the border using the bounds directly\n  ctx.beginPath()\n  ctx.roundRect(x, y, width, height, 8 / canvas.ds.scale)\n  ctx.stroke()\n\n  // Restore context\n  ctx.restore()\n}\n\n/**\n * Extension that adds a dashed selection border for multiple selected nodes\n */\nconst ext = {\n  name: 'Comfy.SelectionBorder',\n\n  async init() {\n    // Hook into the canvas drawing\n    const originalDrawForeground = app.canvas.onDrawForeground\n\n    app.canvas.onDrawForeground = function (\n      ctx: CanvasRenderingContext2D,\n      visibleArea: Rectangle\n    ) {\n      // Call original if it exists\n      originalDrawForeground?.call(this, ctx, visibleArea)\n\n      // Draw our selection border\n      drawSelectionBorder(ctx, app.canvas)\n    }\n  }\n}\n\napp.registerExtension(ext)\n","import { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\n\nimport { app } from '@/scripts/app'\n\nlet touchZooming = false\nlet touchCount = 0\n\napp.registerExtension({\n  name: 'Comfy.SimpleTouchSupport',\n  setup() {\n    let touchDist: number | null = null\n    let touchTime: Date | null = null\n    let lastTouch: { clientX: number; clientY: number } | null = null\n    let lastScale: number | null = null\n    function getMultiTouchPos(e: TouchEvent) {\n      return Math.hypot(\n        e.touches[0].clientX - e.touches[1].clientX,\n        e.touches[0].clientY - e.touches[1].clientY\n      )\n    }\n\n    function getMultiTouchCenter(e: TouchEvent) {\n      return {\n        clientX: (e.touches[0].clientX + e.touches[1].clientX) / 2,\n        clientY: (e.touches[0].clientY + e.touches[1].clientY) / 2\n      }\n    }\n\n    app.canvasEl.parentElement?.addEventListener(\n      'touchstart',\n      (e: TouchEvent) => {\n        touchCount += e.changedTouches.length\n\n        lastTouch = null\n        lastScale = null\n        if (e.touches.length === 1) {\n          // Store start time for press+hold for context menu\n          touchTime = new Date()\n          lastTouch = e.touches[0]\n        } else {\n          touchTime = null\n          if (e.touches.length === 2) {\n            // Store center pos for zoom\n            lastScale = app.canvas.ds.scale\n            lastTouch = getMultiTouchCenter(e)\n\n            touchDist = getMultiTouchPos(e)\n            app.canvas.pointer.isDown = false\n          }\n        }\n      },\n      true\n    )\n\n    app.canvasEl.parentElement?.addEventListener(\n      'touchend',\n      (e: TouchEvent) => {\n        touchCount -= e.changedTouches.length\n\n        if (e.touches.length !== 1) touchZooming = false\n        if (touchTime && !e.touches.length) {\n          if (new Date().getTime() - touchTime.getTime() > 600) {\n            if (e.target === app.canvasEl) {\n              const touch = {\n                button: 2, // Right click\n                clientX: e.changedTouches[0].clientX,\n                clientY: e.changedTouches[0].clientY,\n                pointerId: 1, // changedTouches' id is 0, set it to any number\n                isPrimary: true // changedTouches' isPrimary is false, so set it to true\n              }\n              // context menu info set in 'pointerdown' event\n              app.canvasEl.dispatchEvent(new PointerEvent('pointerdown', touch))\n              // then, context menu open after 'pointerup' event\n              setTimeout(() => {\n                app.canvasEl.dispatchEvent(new PointerEvent('pointerup', touch))\n              })\n              e.preventDefault()\n            }\n          }\n          touchTime = null\n        }\n      }\n    )\n\n    const resetTouchState = () => {\n      touchCount = 0\n      touchZooming = false\n      touchTime = null\n      lastTouch = null\n      lastScale = null\n      touchDist = null\n    }\n\n    // Reset touch state when page loses visibility (e.g., switching apps on iPad)\n    // This prevents touchCount from getting stuck when touchend events are missed\n    document.addEventListener('visibilitychange', () => {\n      if (document.hidden) {\n        resetTouchState()\n      }\n    })\n\n    // Also handle touchcancel which fires when touch is interrupted\n    app.canvasEl.parentElement?.addEventListener('touchcancel', resetTouchState)\n\n    app.canvasEl.parentElement?.addEventListener(\n      'touchmove',\n      (e) => {\n        // make a threshold for touchmove to prevent clear touchTime for long press\n        if (touchTime && lastTouch && e.touches.length === 1) {\n          const onlyTouch = e.touches[0]\n          const deltaX = onlyTouch.clientX - lastTouch.clientX\n          const deltaY = onlyTouch.clientY - lastTouch.clientY\n          if (deltaX * deltaX + deltaY * deltaY > 30) {\n            touchTime = null\n          }\n        }\n        if (e.touches.length === 2 && lastTouch && !e.ctrlKey && !e.shiftKey) {\n          e.preventDefault() // Prevent browser from zooming when two textareas are touched\n          app.canvas.pointer.isDown = false\n          touchZooming = true\n\n          LiteGraph.closeAllContextMenus(window)\n          app.canvas.search_box?.close()\n          const newTouchDist = getMultiTouchPos(e)\n\n          const center = getMultiTouchCenter(e)\n\n          if (lastScale === null || touchDist === null) return\n          let scale = (lastScale * newTouchDist) / touchDist\n\n          const newX = (center.clientX - lastTouch.clientX) / scale\n          const newY = (center.clientY - lastTouch.clientY) / scale\n\n          // Code from LiteGraph\n          if (scale < app.canvas.ds.min_scale) {\n            scale = app.canvas.ds.min_scale\n          } else if (scale > app.canvas.ds.max_scale) {\n            scale = app.canvas.ds.max_scale\n          }\n\n          const oldScale = app.canvas.ds.scale\n\n          app.canvas.ds.scale = scale\n\n          // Code from LiteGraph\n          if (Math.abs(app.canvas.ds.scale - 1) < 0.01) {\n            app.canvas.ds.scale = 1\n          }\n\n          const newScale = app.canvas.ds.scale\n\n          const convertScaleToOffset = (scale: number) => [\n            center.clientX / scale - app.canvas.ds.offset[0],\n            center.clientY / scale - app.canvas.ds.offset[1]\n          ]\n          const oldCenter = convertScaleToOffset(oldScale)\n          const newCenter = convertScaleToOffset(newScale)\n\n          app.canvas.ds.offset[0] += newX + newCenter[0] - oldCenter[0]\n          app.canvas.ds.offset[1] += newY + newCenter[1] - oldCenter[1]\n\n          lastTouch.clientX = center.clientX\n          lastTouch.clientY = center.clientY\n\n          app.canvas.setDirty(true, true)\n        }\n      },\n      true\n    )\n  }\n})\n\nconst processMouseDown = LGraphCanvas.prototype.processMouseDown\nLGraphCanvas.prototype.processMouseDown = function (e: PointerEvent) {\n  const startsFreshTouch = e.pointerType === 'touch' && e.isPrimary\n  if (startsFreshTouch) {\n    touchCount = 0\n    touchZooming = false\n  }\n\n  if (touchZooming || touchCount) {\n    return\n  }\n  app.canvas.pointer.isDown = false // Prevent context menu from opening on second tap\n  return processMouseDown.apply(this, [e])\n}\n\nconst processMouseMove = LGraphCanvas.prototype.processMouseMove\nLGraphCanvas.prototype.processMouseMove = function (e: PointerEvent) {\n  if (touchZooming || touchCount > 1) {\n    return\n  }\n  return processMouseMove.apply(this, [e])\n}\n","import type { ComfyNodeDef } from '@/schemas/nodeDefSchema'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { inputSpecTree, ownSlotTypes } from '@/schemas/nodeDef/inputSpecTree'\nimport { transformNodeDefV1ToV2 } from '@/schemas/nodeDef/migration'\nimport { collectSearchableOutputTypes } from '@/schemas/nodeDef/searchableSlotTypes'\n\nimport { ComfyWidgets } from '../../scripts/widgets'\n\n/**\n * The socket types a node def should be registered under for link-release\n * suggestions.\n *\n * Only required inputs are offered, to keep the menu small, and widget-backed\n * types are skipped unless forced to a socket. Dynamic controls are descended\n * so a type nested in a DynamicCombo option or an Autogrow template is still\n * reachable, matching what node search reports.\n */\nexport function collectRegistrableSlotTypes(nodeData: ComfyNodeDef): {\n  inputTypes: Set<string>\n  outputTypes: string[]\n} {\n  const defV2 = transformNodeDefV1ToV2(nodeData)\n\n  const inputTypes = new Set<string>()\n  for (const rootSpec of Object.values(defV2.inputs)) {\n    collectInputTypes(rootSpec, inputTypes)\n  }\n\n  return {\n    inputTypes,\n    outputTypes: collectSearchableOutputTypes(\n      defV2.outputs,\n      defV2.inputs,\n      nodeData.output_matchtypes\n    )\n  }\n}\n\nfunction collectInputTypes(rootSpec: InputSpecV2, inputTypes: Set<string>) {\n  if (rootSpec.isOptional) return\n\n  for (const spec of inputSpecTree(rootSpec)) {\n    if (!spec.isOptional) addSocketTypes(spec, inputTypes)\n  }\n}\n\nfunction addSocketTypes(spec: InputSpecV2, inputTypes: Set<string>) {\n  for (const type of ownSlotTypes(spec)) {\n    if (!(type in ComfyWidgets) || spec.forceInput) inputTypes.add(type)\n  }\n}\n","import type { SlotTypeDefaultNodeOpts } from '@/lib/litegraph/src/LiteGraphGlobal'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { collectRegistrableSlotTypes } from '@/extensions/core/slotDefaultTypes'\nimport type { ComfyExtension } from '@/types/comfy'\n\nimport { app } from '../../scripts/app'\n\n// Adds defaults for quickly adding nodes with middle click on the input/output\n\ninterface SlotDefaultsExtension extends ComfyExtension {\n  suggestionsNumber: { value: number } | null\n  slot_types_default_out: Record<\n    string,\n    Array<string | SlotTypeDefaultNodeOpts>\n  >\n  slot_types_default_in: Record<string, Array<string | SlotTypeDefaultNodeOpts>>\n  setDefaults(maxNum?: number | null): void\n}\n\napp.registerExtension({\n  name: 'Comfy.SlotDefaults',\n  suggestionsNumber: null,\n  init(this: SlotDefaultsExtension) {\n    LiteGraph.search_filter_enabled = true\n    this.suggestionsNumber = app.ui.settings.addSetting({\n      id: 'Comfy.NodeSuggestions.number',\n      category: ['Comfy', 'Node Search Box', 'NodeSuggestions'],\n      name: 'Number of nodes suggestions',\n      tooltip: 'Only for litegraph searchbox/context menu',\n      type: 'slider',\n      attrs: {\n        min: 1,\n        max: 100,\n        step: 1\n      },\n      defaultValue: 5,\n      onChange: (newVal) => {\n        this.setDefaults(newVal)\n      }\n    })\n  },\n  slot_types_default_out: {},\n  slot_types_default_in: {},\n  async beforeRegisterNodeDef(\n    this: SlotDefaultsExtension,\n    _nodeType,\n    nodeData\n  ) {\n    const nodeId = nodeData.name\n    const { inputTypes, outputTypes } = collectRegistrableSlotTypes(nodeData)\n\n    for (const type of inputTypes) {\n      if (!(type in this.slot_types_default_out)) {\n        this.slot_types_default_out[type] = ['Reroute']\n      }\n      if (this.slot_types_default_out[type].includes(nodeId)) continue\n      this.slot_types_default_out[type].push(nodeId)\n\n      // Input types have to be stored as lower case\n      // Store each node that can handle this input type\n      const lowerType = type.toLocaleLowerCase()\n      if (!(lowerType in LiteGraph.registered_slot_in_types)) {\n        LiteGraph.registered_slot_in_types[lowerType] = { nodes: [] }\n      }\n      LiteGraph.registered_slot_in_types[lowerType].nodes.push(nodeId)\n    }\n\n    for (const type of outputTypes) {\n      if (!(type in this.slot_types_default_in)) {\n        this.slot_types_default_in[type] = ['Reroute']\n      }\n\n      if (this.slot_types_default_in[type].includes(nodeId)) continue\n      this.slot_types_default_in[type].push(nodeId)\n\n      // Store each node that can handle this output type\n      if (!(type in LiteGraph.registered_slot_out_types)) {\n        LiteGraph.registered_slot_out_types[type] = { nodes: [] }\n      }\n      LiteGraph.registered_slot_out_types[type].nodes.push(nodeId)\n\n      if (!LiteGraph.slot_types_out.includes(type)) {\n        LiteGraph.slot_types_out.push(type)\n      }\n    }\n\n    const maxNum = this.suggestionsNumber?.value\n    this.setDefaults(maxNum)\n  },\n  setDefaults(this: SlotDefaultsExtension, maxNum?: number | null) {\n    LiteGraph.slot_types_default_out = {}\n    LiteGraph.slot_types_default_in = {}\n\n    const max = maxNum ?? undefined\n    for (const type in this.slot_types_default_out) {\n      LiteGraph.slot_types_default_out[type] = this.slot_types_default_out[\n        type\n      ].slice(0, max)\n    }\n    for (const type in this.slot_types_default_in) {\n      LiteGraph.slot_types_default_in[type] = this.slot_types_default_in[\n        type\n      ].slice(0, max)\n    }\n  }\n})\n","import type { ResultItemType } from '@/schemas/resultItemTypeSchema'\nimport { app } from '@/scripts/app'\n\nexport function getResourceURL(\n  subfolder: string,\n  filename: string,\n  type: ResultItemType = 'input'\n): string {\n  const params = [\n    'filename=' + encodeURIComponent(filename),\n    'type=' + type,\n    'subfolder=' + subfolder,\n    app.getRandParam().substring(1)\n  ].join('&')\n\n  return `/view?${params}`\n}\n\nexport function splitFilePath(path: string): [string, string] {\n  const folder_separator = path.lastIndexOf('/')\n  if (folder_separator === -1) {\n    return ['', path]\n  }\n  return [\n    path.substring(0, folder_separator),\n    path.substring(folder_separator + 1)\n  ]\n}\n","import { MediaRecorder as ExtendableMediaRecorder } from 'extendable-media-recorder'\n\nimport { useNodeDragAndDrop } from '@/composables/node/useNodeDragAndDrop'\nimport { useNodeFileInput } from '@/composables/node/useNodeFileInput'\nimport { useNodePaste } from '@/composables/node/useNodePaste'\nimport { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { resolveNodeRootGraphId } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IStringWidget\n} from '@/lib/litegraph/src/types/widgets'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  getResourceURL,\n  splitFilePath\n} from '@/renderer/extensions/vueNodes/widgets/utils/audioUtils'\nimport type { NodeExecutionOutput } from '@/platform/remote/comfyui/execution/types'\nimport type { ComfyNodeDef, InputSpec } from '@/schemas/nodeDefSchema'\nimport type { DOMWidget } from '@/scripts/domWidget'\nimport { useAudioService } from '@/services/audioService'\nimport type { NodeLocatorId } from '@/types'\nimport { widgetId } from '@/types/widgetId'\nimport { getErrorMessage } from '@/utils/errorUtil'\nimport { getNodeByLocatorId } from '@/utils/graphTraversalUtil'\n\nimport { api } from '../../scripts/api'\nimport { app } from '../../scripts/app'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\n\nfunction updateUIWidget(\n  audioUIWidget: DOMWidget<HTMLAudioElement, string>,\n  url: string = ''\n) {\n  audioUIWidget.element.src = url\n  audioUIWidget.value = url\n  audioUIWidget.callback?.(url)\n  if (url) audioUIWidget.element.classList.remove('empty-audio-widget')\n  else audioUIWidget.element.classList.add('empty-audio-widget')\n}\n\nfunction appendWidgetValue(widget: IStringWidget, path: string) {\n  const values = widget.options.values\n  if (values && !values.includes(path)) values.push(path)\n}\n\nasync function uploadFile(\n  node: LGraphNode,\n  audioWidget: IStringWidget,\n  audioUIWidget: DOMWidget<HTMLAudioElement, string>,\n  file: File,\n  updateNode: boolean,\n  pasted: boolean = false\n): Promise<boolean> {\n  try {\n    // Wrap file in formdata so it includes filename\n    const body = new FormData()\n    body.append('image', file)\n    if (pasted) body.append('subfolder', 'pasted')\n    const resp = await api.fetchApi('/upload/image', {\n      method: 'POST',\n      body\n    })\n\n    if (resp.status === 200) {\n      const data: { name: string; subfolder?: string } = await resp.json()\n      // Add the file to the dropdown list and update the widget value\n      const path = data.subfolder ? `${data.subfolder}/${data.name}` : data.name\n\n      appendWidgetValue(audioWidget, path)\n\n      if (updateNode) {\n        const oldValue = audioWidget.value\n        updateUIWidget(\n          audioUIWidget,\n          api.apiURL(getResourceURL(...splitFilePath(path)))\n        )\n\n        audioWidget.value = path\n        // Manually trigger the callback to update VueNodes\n        audioWidget.callback?.(path)\n        node.onWidgetChanged?.(audioWidget.name, path, oldValue, audioWidget)\n      }\n      return true\n    } else {\n      useToast().warning(\n        t('g.uploadFailed', { reason: `${resp.status} - ${resp.statusText}` })\n      )\n      return false\n    }\n  } catch (error) {\n    useToast().warning(\n      t('g.uploadFailed', {\n        reason: getErrorMessage(error) ?? t('g.unknownError')\n      })\n    )\n    return false\n  }\n}\n\n// AudioWidget MUST be registered first, as AUDIOUPLOAD depends on AUDIO_UI to be\n// present.\napp.registerExtension({\n  name: 'Comfy.AudioWidget',\n  async beforeRegisterNodeDef(\n    nodeType: typeof LGraphNode,\n    nodeData: ComfyNodeDef\n  ) {\n    const comfyClass = nodeType.prototype.comfyClass\n    if (\n      comfyClass &&\n      [\n        'LoadAudio',\n        'SaveAudio',\n        'PreviewAudio',\n        'SaveAudioMP3',\n        'SaveAudioOpus',\n        'SaveAudioAdvanced'\n      ].includes(comfyClass)\n    ) {\n      const input = (nodeData.input ??= {})\n      const required = (input.required ??= {})\n      required.audioUI = ['AUDIO_UI', {}]\n    }\n  },\n  getCustomWidgets() {\n    return {\n      AUDIO_UI(node: LGraphNode, inputName: string) {\n        const audio = document.createElement('audio')\n        audio.controls = true\n        audio.classList.add('comfy-audio')\n        audio.setAttribute('name', 'media')\n\n        const audioUIWidget: DOMWidget<HTMLAudioElement, string> =\n          node.addDOMWidget(inputName, /* name=*/ 'audioUI', audio)\n        audioUIWidget.serialize = false\n        audioUIWidget.options.serialize = false\n        const { nodeData } = node.constructor\n        if (nodeData == null) throw new TypeError('nodeData is null')\n\n        const isOutputNode = nodeData.output_node\n        if (isOutputNode) {\n          // Hide the audio widget when there is no audio initially.\n          audioUIWidget.element.classList.add('empty-audio-widget')\n          // Populate the audio widget UI on node execution.\n          const onExecuted = node.onExecuted\n          node.onExecuted = function (output: NodeExecutionOutput) {\n            onExecuted?.call(this, output)\n            const audios = output.audio\n            if (!audios?.length) return\n            const audio = audios[0]\n            const resourceUrl = getResourceURL(\n              audio.subfolder ?? '',\n              audio.filename ?? '',\n              audio.type\n            )\n            updateUIWidget(audioUIWidget, api.apiURL(resourceUrl))\n          }\n        }\n\n        audioUIWidget.options.getValue = () => {\n          const value = useWidgetValueStore().getWidget(\n            widgetId(\n              resolveNodeRootGraphId(node, app.rootGraph.id),\n              node.id,\n              inputName\n            )\n          )?.value\n          return typeof value === 'string' ? value : ''\n        }\n        audioUIWidget.options.setValue = (v) => {\n          const graphId = resolveNodeRootGraphId(node, app.rootGraph.id)\n          const widgetState = useWidgetValueStore().getWidget(\n            widgetId(graphId, node.id, inputName)\n          )\n          if (widgetState) widgetState.value = v\n        }\n\n        return { widget: audioUIWidget }\n      }\n    }\n  },\n  onNodeOutputsUpdated(\n    nodeOutputs: Record<NodeLocatorId, NodeExecutionOutput>\n  ) {\n    for (const [nodeLocatorId, output] of Object.entries(nodeOutputs)) {\n      if (!output.audio?.length) continue\n\n      const node = getNodeByLocatorId(app.rootGraph, nodeLocatorId)\n      if (!node) continue\n\n      const audioUIWidget = node.widgets?.find(\n        (w) => w.name === 'audioUI'\n      ) as unknown as DOMWidget<HTMLAudioElement, string>\n      const audio = output.audio[0]\n      const resourceUrl = getResourceURL(\n        audio.subfolder ?? '',\n        audio.filename ?? '',\n        audio.type\n      )\n      updateUIWidget(audioUIWidget, api.apiURL(resourceUrl))\n    }\n  }\n})\n\napp.registerExtension({\n  name: 'Comfy.UploadAudio',\n  async beforeRegisterNodeDef(\n    _nodeType: typeof LGraphNode,\n    nodeData: ComfyNodeDef\n  ) {\n    const required: Partial<Record<string, InputSpec>> | undefined =\n      nodeData.input?.required\n    if (required?.audio?.[1]?.audio_upload === true) {\n      required.upload = ['AUDIOUPLOAD', {}]\n    }\n  },\n  getCustomWidgets() {\n    return {\n      AUDIOUPLOAD(node, inputName: string) {\n        // The widget that allows user to select file.\n        const audioWidget = node.widgets?.find(\n          (w) => w.name === 'audio'\n        ) as IStringWidget\n        const audioUIWidget = node.widgets?.find(\n          (w) => w.name === 'audioUI'\n        ) as unknown as DOMWidget<HTMLAudioElement, string>\n\n        const onAudioWidgetUpdate = () => {\n          const value = audioWidget.value\n          const values = audioWidget.options.values\n          const isEmptySentinel =\n            value === 'none' && values?.length === 1 && values[0] === value\n          updateUIWidget(\n            audioUIWidget,\n            value && !isEmptySentinel\n              ? api.apiURL(getResourceURL(...splitFilePath(value)))\n              : ''\n          )\n        }\n        // Initially load default audio file to audioUIWidget.\n        onAudioWidgetUpdate()\n\n        audioWidget.callback = onAudioWidgetUpdate\n\n        // Load saved audio file widget values if restoring from workflow\n        const onGraphConfigured = node.onGraphConfigured\n        node.onGraphConfigured = function () {\n          onGraphConfigured?.call(this)\n          onAudioWidgetUpdate()\n        }\n\n        const handleUpload = async (files: File[]) => {\n          if (!files.length) return files\n\n          if (node.isUploading) {\n            useToast().warning(t('g.uploadAlreadyInProgress'))\n            return []\n          }\n\n          node.isUploading = true\n          const previousValue = audioWidget.value\n          audioWidget.value = files[0].name\n          try {\n            const success = await uploadFile(\n              node,\n              audioWidget,\n              audioUIWidget,\n              files[0],\n              true\n            )\n            if (!success) {\n              audioWidget.value = previousValue\n            }\n          } finally {\n            node.isUploading = false\n            node.graph?.setDirtyCanvas(true)\n          }\n          return files\n        }\n\n        const isAudioFile = (file: File) => file.type.startsWith('audio/')\n\n        const { openFileSelection } = useNodeFileInput(node, {\n          accept: 'audio/*',\n          onSelect: handleUpload\n        })\n\n        // The widget to pop up the upload dialog.\n        const uploadWidget = node.addWidget(\n          'button',\n          inputName,\n          '',\n          openFileSelection,\n          {\n            serialize: false,\n            surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n          }\n        )\n        uploadWidget.label = t('g.choose_file_to_upload')\n\n        useNodeDragAndDrop(node, {\n          fileFilter: isAudioFile,\n          onDrop: handleUpload\n        })\n\n        useNodePaste(node, {\n          fileFilter: isAudioFile,\n          onPaste: handleUpload\n        })\n\n        node.previewMediaType = 'audio'\n\n        return { widget: uploadWidget }\n      }\n    }\n  }\n})\n\napp.registerExtension({\n  name: 'Comfy.RecordAudio',\n\n  getCustomWidgets() {\n    return {\n      AUDIO_RECORD(node, inputName: string) {\n        const audio = document.createElement('audio')\n        audio.controls = true\n        audio.classList.add('comfy-audio')\n        audio.setAttribute('name', 'media')\n        const audioUIWidget: DOMWidget<HTMLAudioElement, string> =\n          node.addDOMWidget(inputName, /* name=*/ 'audioUI', audio)\n\n        let mediaRecorder: MediaRecorder | null = null\n        let isRecording = false\n        let audioChunks: Blob[] = []\n        let currentStream: MediaStream | null = null\n        let recordWidget: IBaseWidget | null = null\n\n        let stopPromise: Promise<void> | null = null\n        let stopResolve: (() => void) | null = null\n\n        const handleRecordingStartFailure = (error: unknown) => {\n          reportError(error, {\n            surface: 'assets',\n            errorType: 'failure_starting_audio_recorder',\n            tags: {\n              failure_kind: 'caught_unexpected',\n              feature_area: 'assets',\n              operation: 'execute',\n              outcome: 'recovered'\n            },\n            level: 'error'\n          })\n          useToast().warning(t('g.recordingFailedToStart'))\n\n          if (mediaRecorder) {\n            try {\n              mediaRecorder.stop()\n            } catch {\n              // A recorder that never started throws on stop; recovery continues.\n            }\n          }\n          mediaRecorder = null\n          useAudioService().stopAllTracks(currentStream)\n          currentStream = null\n          isRecording = false\n          if (recordWidget) {\n            recordWidget.label = t('g.startRecording')\n          }\n        }\n\n        audioUIWidget.serializeValue = async () => {\n          if (isRecording && mediaRecorder) {\n            stopPromise = new Promise((resolve) => {\n              stopResolve = resolve\n            })\n\n            mediaRecorder.stop()\n\n            await stopPromise\n          }\n\n          const audioSrc = audioUIWidget.element.src\n\n          if (!audioSrc) {\n            useToast().warning(t('g.noAudioRecorded'))\n            return ''\n          }\n\n          const blob = await fetch(audioSrc).then((r) => r.blob())\n\n          return await useAudioService().convertBlobToFileAndSubmit(blob)\n        }\n\n        recordWidget = node.addWidget(\n          'button',\n          inputName,\n          '',\n          async () => {\n            if (isRecording) {\n              mediaRecorder?.stop()\n              return\n            }\n\n            try {\n              currentStream = await navigator.mediaDevices.getUserMedia({\n                audio: true\n              })\n            } catch (err) {\n              if (\n                err instanceof DOMException &&\n                err.name === 'NotAllowedError'\n              ) {\n                console.error('Error accessing microphone:', err)\n                useToast().warning(t('g.micPermissionDenied'))\n                useAudioService().stopAllTracks(currentStream)\n                currentStream = null\n              } else {\n                handleRecordingStartFailure(err)\n              }\n              return\n            }\n\n            try {\n              mediaRecorder = new ExtendableMediaRecorder(currentStream, {\n                mimeType: 'audio/wav'\n              }) as unknown as MediaRecorder\n\n              audioChunks = []\n\n              mediaRecorder.ondataavailable = (event) => {\n                audioChunks.push(event.data)\n              }\n\n              mediaRecorder.onstop = async () => {\n                const audioBlob = new Blob(audioChunks, { type: 'audio/wav' })\n\n                useAudioService().stopAllTracks(currentStream)\n\n                if (\n                  audioUIWidget.element.src &&\n                  audioUIWidget.element.src.startsWith('blob:')\n                ) {\n                  URL.revokeObjectURL(audioUIWidget.element.src)\n                }\n\n                updateUIWidget(audioUIWidget, URL.createObjectURL(audioBlob))\n\n                isRecording = false\n\n                if (recordWidget) {\n                  recordWidget.label = t('g.startRecording')\n                }\n\n                if (stopResolve) {\n                  stopResolve()\n                  stopResolve = null\n                  stopPromise = null\n                }\n              }\n\n              mediaRecorder.onerror = (event) => {\n                console.error('MediaRecorder error:', event)\n                useAudioService().stopAllTracks(currentStream)\n                isRecording = false\n\n                if (recordWidget) {\n                  recordWidget.label = t('g.startRecording')\n                }\n\n                if (stopResolve) {\n                  stopResolve()\n                  stopResolve = null\n                  stopPromise = null\n                }\n              }\n\n              mediaRecorder.start()\n              isRecording = true\n              if (recordWidget) {\n                recordWidget.label = t('g.stopRecording')\n              }\n            } catch (err) {\n              handleRecordingStartFailure(err)\n            }\n          },\n          { serialize: false }\n        )\n\n        recordWidget.label = t('g.startRecording')\n        // Override the type for Vue rendering while keeping 'button' for LiteGraph\n        recordWidget.type = 'audiorecord'\n\n        const originalOnRemoved = node.onRemoved\n        node.onRemoved = function () {\n          if (isRecording && mediaRecorder) {\n            mediaRecorder.stop()\n          }\n          useAudioService().stopAllTracks(currentStream)\n          if (audioUIWidget.element.src.startsWith('blob:')) {\n            URL.revokeObjectURL(audioUIWidget.element.src)\n          }\n          originalOnRemoved?.call(this)\n        }\n\n        return { widget: recordWidget }\n      }\n    }\n  },\n\n  async nodeCreated(node: LGraphNode) {\n    if (node.constructor.comfyClass !== 'RecordAudio') return\n\n    await useAudioService().registerWavEncoder()\n  }\n})\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { isMediaUploadComboInput } from '@/schemas/nodeDefSchema'\nimport type { ComfyNodeDef, InputSpec } from '@/schemas/nodeDefSchema'\n\nimport { app } from '../../scripts/app'\n\n// Adds an upload button to the nodes\n\nconst createUploadInput = (\n  imageInputName: string,\n  imageInputOptions: InputSpec\n): InputSpec => [\n  'IMAGEUPLOAD',\n  {\n    ...imageInputOptions[1],\n    imageInputName\n  }\n]\n\napp.registerExtension({\n  name: 'Comfy.UploadImage',\n  beforeRegisterNodeDef(_nodeType: typeof LGraphNode, nodeData: ComfyNodeDef) {\n    const { input } = nodeData\n    const { required } = input ?? {}\n    if (!required) return\n\n    const found = Object.entries(required).find(([_, input]) =>\n      isMediaUploadComboInput(input)\n    )\n\n    // If media combo input found, attach upload input\n    if (found) {\n      const [inputName, inputSpec] = found\n      required.upload = createUploadInput(inputName, inputSpec)\n    }\n  }\n})\n","import { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { uploadTempFile } from '@/services/uploadTempFile'\n\nimport { app } from '../../scripts/app'\n\nconst webcamReady = new WeakMap<LGraphNode, Promise<HTMLVideoElement>>()\n\napp.registerExtension({\n  name: 'Comfy.WebcamCapture',\n  getCustomWidgets() {\n    return {\n      WEBCAM(node, inputName) {\n        let resolveVideo: (video: HTMLVideoElement) => void = () => undefined\n        webcamReady.set(\n          node,\n          new Promise((resolve) => (resolveVideo = resolve))\n        )\n\n        const container = document.createElement('div')\n        container.style.background = 'rgba(0,0,0,0.25)'\n        container.style.textAlign = 'center'\n\n        const video = document.createElement('video')\n        video.style.height = video.style.width = '100%'\n\n        const loadVideo = async () => {\n          try {\n            const stream = await navigator.mediaDevices.getUserMedia({\n              video: true,\n              audio: false\n            })\n            container.replaceChildren(video)\n\n            setTimeout(() => resolveVideo(video), 500) // Fallback as loadedmetadata doesnt fire sometimes?\n            video.addEventListener(\n              'loadedmetadata',\n              () => resolveVideo(video),\n              false\n            )\n            video.srcObject = stream\n            await video.play()\n          } catch (error) {\n            const label = document.createElement('div')\n            label.style.color = 'red'\n            label.style.overflow = 'auto'\n            label.style.maxHeight = '100%'\n            label.style.whiteSpace = 'pre-wrap'\n\n            const message =\n              error instanceof Error ? error.message : String(error)\n            if (window.isSecureContext) {\n              label.textContent =\n                'Unable to load webcam, please ensure access is granted:\\n' +\n                message\n            } else {\n              label.textContent =\n                'Unable to load webcam. A secure context is required, if you are not accessing ComfyUI on localhost (127.0.0.1) you will have to enable TLS (https)\\n\\n' +\n                message\n            }\n\n            container.replaceChildren(label)\n          }\n        }\n\n        void loadVideo()\n\n        return { widget: node.addDOMWidget(inputName, 'WEBCAM', container) }\n      }\n    }\n  },\n  nodeCreated(node: LGraphNode) {\n    if ((node.type, node.constructor.comfyClass !== 'WebcamCapture')) return\n\n    let video: HTMLVideoElement | undefined\n    const camera = node.widgets?.find((w) => w.name === 'image')\n    const w = node.widgets?.find((w) => w.name === 'width')\n    const h = node.widgets?.find((w) => w.name === 'height')\n    const captureOnQueue = node.widgets?.find(\n      (w) => w.name === 'capture_on_queue'\n    )\n    if (!camera || !w || !h || !captureOnQueue) return\n\n    const canvas = document.createElement('canvas')\n    const nodeOutputStore = useNodeOutputStore()\n\n    const capture = () => {\n      if (\n        !video ||\n        typeof w.value !== 'number' ||\n        typeof h.value !== 'number'\n      ) {\n        return\n      }\n      canvas.width = w.value\n      canvas.height